.model-card__price{display:inline-flex;align-items:center;gap:4px;background:rgba(34,211,168,.12);color:#3ad29f;border:1px solid rgba(34,211,168,.25);padding:3px 9px;border-radius:20px;font-size:11px;font-weight:700}
.model-card__pipe{font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.03em;color:#fdd7b5}
.pipeline-tabs{display:flex;gap:8px;margin-bottom:24px;flex-wrap:wrap}
.pipeline-tab{padding:10px 18px;border-radius:12px;border:1px solid rgba(255,255,255,.1);background:#171411;font-weight:700;font-size:13px;cursor:pointer;color:rgba(255,255,255,.7)}
.pipeline-tab.on{background:rgba(246,164,92,.18);border-color:rgba(250,191,139,.5);color:#fff}
.models-section{margin-bottom:46px;padding-bottom:36px;border-bottom:1px solid rgba(255,255,255,.08)}
.models-section h2{font-size:22px;margin:0 0 4px}
.ver-row{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;text-align:left;background:#140f0b;border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:13px 14px;margin-bottom:9px;cursor:pointer;color:#fff;font:inherit;transition:border-color .15s ease,background .15s ease}
.ver-row:hover{border-color:rgba(250,191,139,.45);background:#1c1814}
.ver-row__label{font-weight:700;font-size:13.5px;margin-bottom:2px}
.ver-row__desc{color:rgba(255,255,255,.55);font-size:12px;line-height:1.4}
.ver-fam-head{display:flex;align-items:center;gap:12px;margin-bottom:18px}
.ver-fam-head img{width:36px;height:36px;border-radius:10px;background:#fff;object-fit:contain;padding:5px}
.model-card--hybrid{background:linear-gradient(160deg,rgba(246,164,92,.17),rgba(23,20,17,.9));border-color:rgba(250,191,139,.5)}
.model-card--hybrid:hover{border-color:rgba(250,191,139,.85);background:linear-gradient(160deg,rgba(246,164,92,.26),rgba(28,24,20,.95))}
.model-card--hybrid .model-card__logo{background:#140f0b;border:1px solid rgba(250,191,139,.35)}
.model-card--hybrid .model-card__logo img{width:30px;height:30px}
.model-card__vcount--auto{color:#fff;background:linear-gradient(135deg,#f6a45c,#d97b28);border-color:transparent;letter-spacing:.06em}
.spec-label{display:block;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:rgba(255,255,255,.45);margin:14px 0 6px}
.spec-row:first-child .spec-label{margin-top:2px}
.gen-price-note{font-size:11.5px;color:rgba(255,255,255,.45);margin-top:8px;text-align:center}
.hist-spec{color:rgba(255,255,255,.5);font-size:11.5px;margin-top:2px}

/* ---- account sub-pages: Usage / Billing / Referral / Settings ---- */
.subpage-head{margin-bottom:26px}
.subpage-head h1{margin:0 0 4px}
.section-h{font-size:15px;font-weight:750;margin:0 0 14px;display:flex;align-items:center;justify-content:space-between}
.meter{height:8px;border-radius:20px;background:rgba(255,255,255,.08);overflow:hidden;margin-top:10px}
.meter__fill{height:100%;border-radius:20px;background:linear-gradient(90deg,#f6a45c,#3ad29f)}
.bar-chart{display:flex;align-items:flex-end;gap:10px;height:120px;margin-top:8px}
.bar-chart__col{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:8px}
.bar-chart__bar{width:100%;max-width:34px;border-radius:6px 6px 2px 2px;background:linear-gradient(180deg,#fabf8b,#d97b28);min-height:4px}
.bar-chart__lbl{font-size:10.5px;color:rgba(255,255,255,.45);font-weight:600}
.usage-row{display:flex;align-items:center;gap:14px;padding:12px 0;border-bottom:1px solid rgba(255,255,255,.06)}
.usage-row:last-child{border-bottom:0}
.usage-row__logo{width:32px;height:32px;border-radius:9px;background:#fff;display:flex;align-items:center;justify-content:center;flex-shrink:0;overflow:hidden}
.usage-row__logo img{width:20px;height:20px;object-fit:contain}
.usage-row__name{font-weight:700;font-size:13.5px}
.usage-row__pct{font-size:11.5px;color:rgba(255,255,255,.45)}
.usage-row__meter{flex:1;height:6px;border-radius:20px;background:rgba(255,255,255,.08);overflow:hidden;margin-top:5px}
.usage-row__fill{height:100%;border-radius:20px;background:#f6a45c}
.usage-row__credits{font-weight:700;font-size:13.5px;color:#3ad29f;flex-shrink:0}
.switch{position:relative;display:inline-block;width:40px;height:23px;flex-shrink:0}
.switch input{opacity:0;width:0;height:0}
.switch__track{position:absolute;inset:0;background:rgba(255,255,255,.14);border-radius:30px;cursor:pointer;transition:.18s}
.switch__track:before{content:'';position:absolute;width:17px;height:17px;left:3px;top:3px;background:#fff;border-radius:50%;transition:.18s}
.switch input:checked+.switch__track{background:#f6a45c}
.switch input:checked+.switch__track:before{transform:translateX(17px)}
.settings-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 0;border-bottom:1px solid rgba(255,255,255,.06)}
.settings-row:last-child{border-bottom:0}
.settings-row__label{font-weight:700;font-size:13.5px}
.settings-row__sub{font-size:12px;color:rgba(255,255,255,.5);margin-top:2px;max-width:420px}
.field{margin-bottom:16px}
.field label{display:block;font-size:12px;font-weight:700;color:rgba(255,255,255,.6);margin-bottom:6px}
.field input[type=text],.field input[type=email]{width:100%;background:#140f0b;border:1px solid rgba(255,255,255,.12);border-radius:10px;padding:11px 13px;color:#fff;font:inherit}
.copybox{display:flex;gap:8px;align-items:center}
.copybox input{flex:1;background:#140f0b;border:1px solid rgba(255,255,255,.12);border-radius:10px;padding:11px 13px;color:#fdd7b5;font:13px/1 ui-monospace,monospace}
table.simple-table{width:100%;border-collapse:collapse;font-size:13px}
table.simple-table th{text-align:left;color:rgba(255,255,255,.45);font-size:11px;text-transform:uppercase;letter-spacing:.04em;font-weight:700;padding:0 0 10px;border-bottom:1px solid rgba(255,255,255,.08)}
table.simple-table td{padding:12px 0;border-bottom:1px solid rgba(255,255,255,.06);vertical-align:middle}
table.simple-table tr:last-child td{border-bottom:0}
.status-pill{display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:700;padding:3px 10px;border-radius:20px}
.status-pill.ok{background:rgba(34,211,168,.12);color:#3ad29f;border:1px solid rgba(34,211,168,.25)}
.status-pill.wait{background:rgba(251,191,36,.12);color:#fbbf24;border:1px solid rgba(251,191,36,.3)}
.status-pill.err{background:rgba(248,113,113,.12);color:#f87171;border:1px solid rgba(248,113,113,.3)}
.plan-card{position:relative;background:#171411;border:1px solid rgba(255,255,255,.08);border-radius:16px;padding:22px}
.plan-card.on{border-color:rgba(250,191,139,.6);background:linear-gradient(160deg,rgba(246,164,92,.14),rgba(23,20,17,.9))}
.plan-card__badge{position:absolute;top:-11px;right:18px;background:linear-gradient(135deg,#f6a45c,#d97b28);color:#fff;font-size:10.5px;font-weight:700;padding:4px 11px;border-radius:20px}
.plan-card__price{font-size:28px;font-weight:800;margin:8px 0 14px}
.plan-card__price span{font-size:13px;color:rgba(255,255,255,.45);font-weight:600}
.plan-card ul{list-style:none;margin:0 0 18px;padding:0;display:flex;flex-direction:column;gap:9px;font-size:12.5px;color:rgba(255,255,255,.7)}
.plan-card li{display:flex;align-items:flex-start;gap:8px}
.plan-card li svg{width:14px;height:14px;color:#3ad29f;flex-shrink:0;margin-top:2px}
.avatar-lg{width:56px;height:56px;border-radius:50%;background:linear-gradient(135deg,#f6a45c,#d97b28);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:20px;color:#fff;flex-shrink:0}
.danger-box{border:1px solid rgba(248,113,113,.3);background:rgba(248,113,113,.05);border-radius:14px;padding:18px}

/* V7: explicit modes, readable cards and a persistent action area. */
.muted,.model-card__desc,.ver-row__desc,.gen-price-note,.studio,label{color:#cabeb4}
.spec-label{color:#c9bdb2!important}.l{color:#c3b5a9}.model-card__vcount,.model-card__pipe{font-size:11px}
.studio-kicker{font-size:11px;letter-spacing:.14em;color:#fdd7b5;font-weight:800;margin-bottom:16px;display:flex;align-items:center;gap:14px}
.studio-kicker span{font-size:10px;letter-spacing:.06em;padding:5px 8px;border:1px solid #5c4837;border-radius:6px;color:#d9cdc2}
#videos-top .img-catalog__head h1{font-size:34px;letter-spacing:-1px;margin-bottom:10px}
#videos-top .img-catalog__head{margin-bottom:28px}
.pipeline-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0 0 32px}
.pipeline-tab{display:flex;align-items:center;gap:12px;padding:19px 16px;text-align:left;min-height:90px;background:#1d1712;border:1px solid #463d35;color:#e0d8d1}
.pipeline-tab.on{background:linear-gradient(115deg,#4f3620,#2f2217);border-color:#ffbe86;box-shadow:inset 0 0 0 1px #c69162}
.pipeline-tab strong{display:block;font-size:15px;color:#fff}.pipeline-tab small{display:block;font-size:12px;font-weight:400;margin-top:6px;color:#d4c9bf;line-height:1.4}
.mode-icon{display:grid;place-items:center;min-width:36px;height:36px;border-radius:10px;background:#ffffff0d;font-size:23px;color:#ffd0a7}.mode-arrow{margin-left:auto;color:#ffd0a7}
.model-card{min-height:215px;padding:20px;border-radius:16px;border-color:#3f3730;gap:12px}
.model-card__name{font-size:15px}.model-card__desc{line-height:1.6;min-height:38px}.model-card__foot{margin-top:auto;gap:8px}.model-card__price{font-size:12px;white-space:nowrap}
.card-spec-hint{font-size:12px;color:#d4c1b0;line-height:1.5}.model-card--hybrid{border-color:#be9067}
.ver-row__desc{overflow-wrap:anywhere;line-height:1.65}.ver-row__main{min-width:0}.ver-spec{display:block;margin-top:7px;color:#f6e1ce;font-size:12px}
#genModal .modal{display:flex;flex-direction:column;padding:0;overflow:hidden;max-height:calc(100dvh - 36px)}
.gen-body{overflow-y:auto;padding:26px;min-height:0;overscroll-behavior:contain}.gen-footer{flex-shrink:0;background:#281f18;border-top:1px solid #4f4134;padding:16px 26px 18px}
.gen-footer>div[style]{margin-top:12px!important}.footer-summary{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:13px;color:#e2d7ce}.footer-summary small{display:block;color:#bbaea2;font-size:10px;letter-spacing:.08em;margin-top:4px}.footer-summary strong{font-size:22px;color:#fde4cf}.gen-price-note{font-size:12px;line-height:1.45}
.model-info{padding:12px;border:1px solid #514235;border-radius:10px;background:#a78bfa0a;font-size:12px;line-height:1.7;color:#d4c8be;margin:14px 0;overflow-wrap:anywhere}.model-info strong{color:#ffe9d5}.spec-row{align-items:flex-start}.spec-label{min-width:65px}.chiprow{flex-wrap:wrap;gap:7px}
button:focus-visible,a:focus-visible{outline:2px solid #ffd4af;outline-offset:4px}.btn:disabled{opacity:.5;cursor:not-allowed}
@media(max-width:700px){.model-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.model-card{min-width:0;padding:14px}.model-card__foot{flex-wrap:wrap}.pipeline-tabs{grid-template-columns:1fr;gap:8px;margin-bottom:24px}.pipeline-tab{min-height:72px;padding:12px 14px}.pipeline-tab small{margin-top:3px}.model-card{min-height:210px}.gen-body{padding:20px}.gen-footer{padding:14px 20px}#videos-top .img-catalog__head h1{font-size:28px}.ov{padding:10px}#genModal .modal{max-height:calc(100dvh - 20px)}}

/* Render the locally hosted vendor marks in legacy family cards as well. */
.model-card[data-logo] .model-card__logo{background:#fff9f3!important}
.model-card[data-logo*="luma-ai-white"] .model-card__logo{background:#1d1814!important}
.model-card[data-logo] .model-card__logo img{width:80%;height:80%;object-fit:contain}

.model-card,.model-card>div{min-width:0}.model-card__foot{flex-wrap:wrap}.model-card__name,.model-card__desc{overflow-wrap:anywhere}
</style>
<style>.mockup-tag{position:fixed;top:14px;right:14px;background:#f6a45c;color:#fff;font:700 12px/1 ui-sans-serif;padding:8px 13px;border-radius:20px;z-index:100;box-shadow:0 6px 20px rgba(0,0,0,.4)}</style>
<style>.prompt-helper{margin:14px 0 18px;padding:14px;border:1px solid #5e4e40;border-radius:14px;background:linear-gradient(120deg,#30251b,#1f1b17)}
.prompt-helper [hidden]{display:none!important}.prompt-helper #paToggle{width:100%;text-align:left;justify-content:flex-start;color:#ffe0c5}.pa-heading{font-size:15px;font-weight:650;margin:18px 0 6px}.pa-note{font-size:12px;line-height:1.6;color:#cec2b8;margin:9px 0;overflow-wrap:anywhere}.prompt-helper textarea{width:100%;box-sizing:border-box;resize:vertical;min-height:76px}.prompt-helper .btn{white-space:normal;min-height:40px}.pa-options{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0}.pa-options button{border:1px solid #635950;background:#302821;color:#efe6df;border-radius:9px;padding:8px 10px;font:inherit;font-size:12px;cursor:pointer}.pa-options button[aria-pressed=true]{background:#9e6c40;border-color:#eeb98b;color:white}.prompt-helper button:focus-visible,.prompt-helper textarea:focus-visible{outline:2px solid #ffcda1;outline-offset:3px}.prompt-helper button:disabled{opacity:.5;cursor:wait}.prompt-helper label{display:block;line-height:1.5}.pa-error{color:#ffb5ad}.pa-question{border-top:1px solid #423830;margin-top:14px;padding-top:12px}
</style>
<style>
/* generation loading overlay — plays between "Generate" and the maintenance notice */
.lx15-load__ring{position:relative;width:88px;height:88px;margin:0 auto 22px}
.lx15-load__r1{position:absolute;inset:0;border-radius:50%;border:4px solid transparent;border-top-color:#ff7a12;border-right-color:#ff7a12;animation:lx15spin9a 1.1s linear infinite;filter:drop-shadow(0 0 7px rgba(255,122,18,.65))}
.lx15-load__r2{position:absolute;inset:16px;border-radius:50%;border:4px solid transparent;border-bottom-color:#ffae3d;border-left-color:#ffae3d;animation:lx15spin9b 1.4s linear infinite;filter:drop-shadow(0 0 7px rgba(255,174,61,.55))}
.lx15-load__core{position:absolute;inset:30px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#ffa94d,#d9610a 70%);display:flex;align-items:center;justify-content:center;box-shadow:0 0 20px 3px rgba(255,122,18,.45)}
.lx15-load__core img{width:20px;height:20px;filter:brightness(0) invert(1)}
@keyframes lx15spin9a{to{transform:rotate(360deg)}}
@keyframes lx15spin9b{to{transform:rotate(-360deg)}}
.lx15-load__status{margin:0 0 16px;font-size:13.5px;color:rgba(255,255,255,.65);min-height:18px;transition:opacity .2s ease}
.lx15-load__bar{height:4px;border-radius:20px;background:rgba(255,255,255,.08);overflow:hidden}
.lx15-load__fill{height:100%;width:0%;border-radius:20px;background:linear-gradient(90deg,#ff7a12,#ffae3d);transition:width 1.9s cubic-bezier(.22,.8,.26,1)}
</style>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Inter+Tight:wght@600;700;800&display=swap" rel="stylesheet"><style id="v14">/* ===== Neuravision Studio v14 — design layer ================================= */
:root{
  --v50:#fff7f0;--v100:#ffecdc;--v200:#f9d8bc;--v300:#f3c49b;--v400:#eeb17b;
  --v500:#f6a45c;--v600:#dd8c45;--v700:#b46f33;--v800:#764a23;--v900:#503116;--v950:#2c1b0c;
  --bg:#0c0906;--surf:#191410;--surf2:#1f1a15;--surf3:#26201a;
  --line:rgba(255,255,255,.075);--line2:rgba(255,255,255,.13);
  --ink:#f7f0ea;--ink2:rgba(247,240,234,.64);--ink3:rgba(247,240,234,.42);
  --ok:#3ad29f;
  --r1:10px;--r2:14px;--r3:20px;
  --sh1:inset 0 1px 0 rgba(255,255,255,.055);
  --sh2:inset 0 1px 0 rgba(255,255,255,.055),0 1px 2px rgba(0,0,0,.45);
  --sh3:inset 0 1px 0 rgba(255,255,255,.07),0 18px 46px -18px rgba(0,0,0,.85);
}
html,body{background:var(--bg)}
body{
  font-family:'Inter',ui-sans-serif,system-ui,'Segoe UI',Roboto,Arial;
  font-feature-settings:'ss01','cv11';
  -webkit-font-smoothing:antialiased;letter-spacing:-.006em;color:var(--ink);
}
body:before{
  content:'';position:fixed;inset:0;pointer-events:none;z-index:0;
  background:
    radial-gradient(900px 520px at 22% -8%,rgba(246,164,92,.13),transparent 62%),
    radial-gradient(700px 420px at 92% 0%,rgba(210,134,68,.10),transparent 60%),
    radial-gradient(1000px 700px at 50% 108%,rgba(246,164,92,.055),transparent 62%);
}
.app{position:relative;z-index:1}
.num,.big,.model-card__price,.footer-summary strong,.time,.nav-count,
.credpill,.hist-spec{font-variant-numeric:tabular-nums}

/* ---- display type ---------------------------------------------------- */
h1,h2,h3,.disp,.big,.brand{font-family:'Inter Tight','Inter',ui-sans-serif,system-ui,Arial}
.panel>h1,.img-catalog__head h1,#videos-top .img-catalog__head h1,.subpage-head h1{
  text-align:left!important;font-size:clamp(28px,3.4vw,38px);font-weight:800;
  letter-spacing:-.032em;line-height:1.08;margin:0 0 8px;
}
.panel h2,.models-section>h2,.img-section__head h2{
  text-align:left!important;font-size:21px;font-weight:750;letter-spacing:-.022em;margin:0 0 4px;
}
.lead{font-size:14.5px;max-width:62ch;margin:0 0 26px;color:var(--ink2)}
.muted{color:var(--ink2)}
.eyebrow{color:var(--v200);opacity:.9}

/* ---- surfaces & radii ------------------------------------------------ */
.card,.model-card,.vcard,.img-product,.keybox,.sched,.socbtn,.feat,.modal{
  border-radius:var(--r2);border-color:var(--line);
}
.card,.feat,.modal{border-radius:var(--r3)}
.btn,.chip,.qchip,.img-cat,input,select,textarea,.copy,.btn-sm{border-radius:var(--r1)}
.card{background:linear-gradient(180deg,var(--surf2),var(--surf));box-shadow:var(--sh2)}
.model-card,.img-product,.vcard{background:linear-gradient(180deg,var(--surf2),var(--surf));box-shadow:var(--sh2);transition:transform .18s ease,border-color .18s ease,box-shadow .18s ease}
.model-card:hover,.img-product:hover,.vcard:hover{
  transform:translateY(-2px);border-color:rgba(250,191,139,.32);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 14px 34px -16px rgba(190,113,45,.7);
}
.modal{background:linear-gradient(180deg,#231c16,#191410);box-shadow:var(--sh3)}
.bar{background:rgba(12,9,6,.82);border-bottom:1px solid var(--line)}
.sb{background:linear-gradient(180deg,rgba(20,16,12,.86),rgba(15,12,9,.86));border-right:1px solid var(--line)}
.nav{border-radius:var(--r1);transition:background .15s ease,color .15s ease}
.nav.on{background:linear-gradient(90deg,rgba(246,164,92,.22),rgba(246,164,92,.07));box-shadow:var(--sh1)}
.nav-count{margin-left:auto;font-size:11px;font-weight:700;color:var(--v200);
  background:rgba(250,191,139,.15);border:1px solid rgba(250,191,139,.25);
  padding:1px 7px;border-radius:20px;min-width:20px;text-align:center}
.nav-count:empty{display:none}

/* ---- buttons --------------------------------------------------------- */
.btn-pri{background:linear-gradient(180deg,var(--v400),var(--v600));box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 8px 20px -10px rgba(237,142,58,.9)}
.btn-pri:hover{background:linear-gradient(180deg,#ffc088,var(--v500))}
.btn-ghost{background:rgba(255,255,255,.045);border:1px solid var(--line2)}
.btn-ghost:hover{background:rgba(255,255,255,.08)}
.lnk{color:var(--v200);font-weight:600}

/* ---- monogram model marks ------------------------------------------- */
.model-card__logo{background:transparent!important;border:1px solid var(--line);
  border-radius:var(--r1);overflow:hidden}
.mono{display:grid;place-items:center;width:100%;height:100%;
  background:linear-gradient(160deg,rgba(250,191,139,.20),rgba(255,255,255,.02));
  color:var(--v100);font:800 13px/1 'Inter Tight','Inter',Arial;letter-spacing:-.02em}
.mono.lg{font-size:16px}
.ver-fam-head .mono,.gen-mono{border-radius:var(--r1)}

/* ---- price in money -------------------------------------------------- */
.model-card__price{border-radius:20px}
.usd{display:block;font-size:10px;font-weight:600;color:var(--ink3);margin-top:2px;letter-spacing:0}
.model-card__foot{align-items:flex-start}
.footer-summary small{color:var(--ink3)}

/* ---- catalog cards --------------------------------------------------- */
.img-product__badge{background:rgba(18,13,8,.72)!important;backdrop-filter:blur(8px);
  border:1px solid rgba(255,255,255,.14);color:#fff;font-weight:650;letter-spacing:-.01em}
.img-product__genre{position:absolute;top:9px;right:9px;font-size:10.5px;font-weight:700;
  padding:3px 8px;border-radius:20px;color:var(--v100);background:rgba(36,24,14,.72);
  backdrop-filter:blur(8px);border:1px solid rgba(250,191,139,.28);letter-spacing:.01em}
.img-product__media{border-radius:var(--r2) var(--r2) 0 0}
.fav-btn{z-index:3}

/* ---- quick chips ----------------------------------------------------- */
.quickchips{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 22px}
.qchip{background:rgba(255,255,255,.04);border:1px solid var(--line2);color:var(--ink2);
  font:600 12.5px/1 'Inter',Arial;padding:9px 13px;cursor:pointer;transition:.15s}
.qchip:hover{color:#fff;border-color:rgba(250,191,139,.4)}
.qchip.on{background:rgba(246,164,92,.2);border-color:rgba(250,191,139,.55);color:#fff}
.img-cats{gap:8px}
.img-cat{font-weight:600}

/* ---- overview -------------------------------------------------------- */
.stat-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:20px}
.stat .big{font-size:38px;letter-spacing:-.03em;margin:4px 0 6px}
.resume{display:flex;gap:18px;align-items:center;flex-wrap:wrap}
.resume__thumb{width:104px;height:66px;border-radius:var(--r1);overflow:hidden;flex-shrink:0;
  background:#120e0a;border:1px solid var(--line);position:relative}
.resume__thumb video,.resume__thumb img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.resume__body{flex:1;min-width:200px}
.sec-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin:32px 0 14px}
.ov-picks{margin-bottom:4px}
#ovPicks.img-products{grid-template-columns:repeat(4,minmax(0,1fr))}
#ovRecent .vcard{margin:0}

/* ---- empty states ---------------------------------------------------- */
.hist-empty,.empty{text-align:center;padding:56px 24px;border:1px dashed var(--line2);
  border-radius:var(--r3);background:rgba(255,255,255,.015)}
.empty__ico{width:46px;height:46px;margin:0 auto 14px;border-radius:50%;display:grid;place-items:center;
  background:rgba(246,164,92,.14);border:1px solid rgba(250,191,139,.3);color:var(--v200)}
.empty__ico svg{width:22px;height:22px}
.empty h3{margin:0 0 6px;font-size:17px;font-weight:750}
.empty p{margin:0 auto 16px;max-width:42ch;color:var(--ink2);font-size:13.5px;line-height:1.6}

/* ---- reward on finish ------------------------------------------------ */
@keyframes lxReveal{from{opacity:0;transform:translateY(10px) scale(.985);filter:blur(7px)}
 to{opacity:1;transform:none;filter:blur(0)}}
@keyframes lxGlow{0%,100%{box-shadow:0 0 0 0 rgba(246,164,92,0)}
 35%{box-shadow:0 0 0 4px rgba(246,164,92,.28),0 18px 40px -18px rgba(246,164,92,.9)}}
.vcard.is-new{animation:lxReveal .55s cubic-bezier(.22,1,.36,1) both,lxGlow 2.2s ease .4s 1}
.vcard.is-new .vthumb:after{content:'';position:absolute;inset:0;border-radius:inherit;
  background:linear-gradient(120deg,transparent 35%,rgba(255,255,255,.16),transparent 65%);
  animation:lxSheen 1.2s ease .3s 1;pointer-events:none}
@keyframes lxSheen{from{transform:translateX(-100%)}to{transform:translateX(100%)}}

/* ---- progress screen (approved orbit layout) ------------------------- */
.lxp-ov{align-items:center;justify-content:center;padding:24px}
.lxp-ov.on{display:flex}
.lxp{width:100%;max-width:640px;display:flex;flex-direction:column;align-items:center;text-align:center}
.lxp .orbit{width:138px;height:138px;position:relative;display:grid;place-items:center;margin-bottom:22px}
.lxp .orbit img{width:96px;height:96px;animation:lxBreathe 3.6s ease-in-out infinite}
.lxp .track{position:absolute;inset:0;border:1px dashed rgba(246,164,92,.28);border-radius:50%;animation:lxSpin 12s linear infinite}
.lxp .track i{position:absolute;width:7px;height:7px;background:#ffc18a;box-shadow:0 0 12px rgba(255,193,138,.55);border-radius:50%;top:24px;right:5px}
.lxp .track i:nth-child(2){top:auto;bottom:8px;right:23px;opacity:.5}
.lxp .track i:nth-child(3){top:54px;left:-3px;opacity:.4}
.lxp .pill{font-size:12px;color:var(--v200);border:1px solid rgba(250,191,139,.22);
  background:rgba(246,164,92,.08);border-radius:24px;padding:8px 14px;display:inline-flex;align-items:center;gap:8px;font-weight:600}
.lxp .pill i{width:6px;height:6px;background:#fabf8b;border-radius:50%;animation:lxBreathe 2s infinite}
.lxp h2{font-size:clamp(26px,4vw,34px)!important;letter-spacing:-.034em;line-height:1.12;margin:20px 0 10px;text-align:center!important}
.lxp-lead{font-size:14.5px;line-height:1.7;color:var(--ink2);margin:0 0 26px}
.lxp .progress{width:100%;max-width:430px;margin:0 0 20px}
.lxp .labels{display:flex;justify-content:space-between;font-size:12px;color:var(--ink3);margin-bottom:11px}
.lxp .labels strong{color:var(--v100);font-size:15px}
.lxp .meter{height:6px;background:rgba(255,255,255,.055);border-radius:10px;overflow:hidden}
.lxp .fill{height:100%;width:0;background:linear-gradient(90deg,var(--v700),var(--v300));border-radius:10px;position:relative;transition:width .45s linear}
.lxp .fill:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.5),transparent);animation:lxSheen2 2.4s linear infinite}
.lxp .time{display:flex;justify-content:space-between;gap:12px;margin-top:12px;font-size:12px;color:var(--ink3)}
.lxp .meta{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin:0 0 22px}
.lxp .meta span{font-size:11px;color:var(--ink2);padding:6px 10px;border:1px solid var(--line);border-radius:8px;background:rgba(255,255,255,.02)}
.lxp-actions{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}
.lxp .status{min-height:20px;color:var(--v200);font-size:12px;margin-top:14px}
.lxp .hint{font-size:12px;color:var(--ink3);margin-top:18px;max-width:44ch;line-height:1.6}
@keyframes lxSpin{to{transform:rotate(360deg)}}
@keyframes lxBreathe{50%{transform:scale(1.065);filter:drop-shadow(0 0 14px rgba(246,164,92,.45))}}
@keyframes lxSheen2{from{transform:translateX(-100%)}to{transform:translateX(100%)}}

/* ---- misc cleanup ---------------------------------------------------- */
.mockup-tag,.fbnotice{display:none!important}
.studio-kicker{color:var(--v200)}
.hist-spec{color:var(--ink3)}
.vbody .t{letter-spacing:-.015em}
::selection{background:rgba(246,164,92,.4)}
*::-webkit-scrollbar{width:10px;height:10px}
*::-webkit-scrollbar-thumb{background:rgba(255,255,255,.1);border-radius:10px;border:3px solid transparent;background-clip:content-box}
*::-webkit-scrollbar-track{background:transparent}

@media(max-width:900px){
  .stat-row{grid-template-columns:1fr}
  #ovPicks.img-products{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sec-head{flex-direction:column;align-items:flex-start;gap:6px}
}
@media(max-width:600px){
  .lxp .orbit{width:112px;height:112px}.lxp .orbit img{width:80px;height:80px}
  .lxp-actions{flex-direction:column;width:100%}.lxp-actions .btn{width:100%}
  .quickchips{margin-bottom:16px}
}
@media(prefers-reduced-motion:reduce){
  *,*:after,*:before{animation:none!important;transition:none!important}
}
</style><style id="lx15-style">
/* ===== Neuravision Studio v15 — additive layer =================================
   Every selector is namespaced .lx15* so it cannot collide with the names
   already taken in V14 (.track/.fill/.meter/.pill/.progress/.time/.meta…). */

/* --- language switcher ---------------------------------------------------- */
.lx15-lang{display:flex;gap:4px;align-items:center;margin:2px 4px 10px;padding:4px;
  border:1px solid rgba(255,255,255,.08);border-radius:12px;background:rgba(255,255,255,.03)}
.lx15-lang b{font:700 10px/1 ui-sans-serif,system-ui;letter-spacing:.08em;opacity:.45;
  text-transform:uppercase;padding:0 6px;flex-shrink:0}
.lx15-lang button{flex:1;border:0;cursor:pointer;border-radius:8px;padding:6px 8px;
  font:700 12px/1 ui-sans-serif,system-ui;color:#d6cfc9;background:transparent;transition:.15s}
.lx15-lang button:hover{background:rgba(255,255,255,.06);color:#fff}
.lx15-lang button[aria-pressed="true"]{background:linear-gradient(135deg,#f6a45c,#d97b28);color:#fff}

/* --- desktop app promo ---------------------------------------------------- */
/* Small card. The owner asked for a compact window on the home panel only:
   one line of copy, two chips, one small button — it must not compete with the
   studio itself, so no hero padding, no glow, capped width. */
.lx15-desk{position:relative;box-sizing:border-box;max-width:560px;
  margin:0 0 26px;padding:12px 14px;
  border:1px solid rgba(246,164,92,.34);border-radius:14px;
  background:linear-gradient(135deg,rgba(246,164,92,.13),rgba(255,255,255,.02));
  display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.lx15-desk *{min-width:0}
.lx15-desk__ico{width:34px;height:34px;border-radius:10px;flex-shrink:0;display:flex;
  align-items:center;justify-content:center;background:rgba(255,255,255,.06);
  border:1px solid rgba(255,255,255,.12)}
.lx15-desk__ico svg{width:19px;height:19px;stroke:#fdd7b5;fill:none;stroke-width:1.7}
.lx15-desk__body{flex:1 1 240px;min-width:0}
.lx15-desk__title{margin:0 0 2px;font:700 13.5px/1.3 ui-sans-serif,system-ui;color:#fff}
.lx15-desk__text{margin:0;font-size:12px;line-height:1.45;color:#bbb1a9}
.lx15-desk__chips{display:flex;gap:5px;margin-top:6px}
.lx15-desk__chips i{font-style:normal;font-size:10.5px;color:#fdd7b5;
  background:rgba(246,164,92,.16);border:1px solid rgba(246,164,92,.3);
  border-radius:999px;padding:2px 7px}
.lx15-desk .btn{flex-shrink:0;padding:7px 13px;font-size:12px}

/* --- negative prompt block ------------------------------------------------ */
.lx15-neg{margin:12px 0 4px}
.lx15-neg__head{display:flex;align-items:flex-start;gap:9px;cursor:pointer;user-select:none}
.lx15-neg__head input{margin:2px 0 0;width:16px;height:16px;accent-color:#f6a45c;flex-shrink:0;cursor:pointer}
.lx15-neg__head span{font-size:13px;font-weight:600;color:#e4ddd6;line-height:1.4}
.lx15-neg__body{margin-top:10px}
.lx15-neg__body[hidden]{display:none}
.lx15-neg textarea{width:100%;min-height:62px;resize:vertical;border-radius:10px;padding:10px 12px;
  font:400 13px/1.5 ui-sans-serif,system-ui;color:#f2ede8;background:#120f0c;
  border:1px solid #3a332c;outline:none}
.lx15-neg textarea:focus{border-color:#f6a45c}
.lx15-neg__presets{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}
.lx15-neg__presets button{cursor:pointer;border-radius:999px;padding:5px 11px;font:600 11.5px/1 ui-sans-serif,system-ui;
  color:#d6cfc9;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);transition:.15s}
.lx15-neg__presets button:hover{background:rgba(246,164,92,.22);border-color:rgba(246,164,92,.5);color:#fff}
.lx15-neg__hint{margin:8px 0 0;font-size:11.5px;line-height:1.5;color:#a3988f}
.lx15-neg__hint.is-warn{color:#f5b971}

/* Venice cards reuse V14's .model-card slots, which were sized for "48 cr".
   Our labels can be longer, so let them wrap instead of widening the grid. */
[data-lx15-model] .model-card__price{max-width:100%;overflow-wrap:anywhere;text-align:right}
[data-lx15-model] .model-card__desc{overflow-wrap:anywhere}

/* --- model profile strip -------------------------------------------------- */
.lx15-prof{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0 0}
.lx15-prof span{font:600 11px/1 ui-sans-serif,system-ui;letter-spacing:.02em;padding:5px 9px;border-radius:999px;
  color:#c6bdb6;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1)}
.lx15-prof span.is-good{color:#7ee0b4;background:rgba(58,210,159,.12);border-color:rgba(58,210,159,.3)}
.lx15-prof span.is-warn{color:#f5b971;background:rgba(245,185,113,.12);border-color:rgba(245,185,113,.3)}
.lx15-prof span.is-nsfw{color:#ff9db1;background:rgba(255,107,139,.12);border-color:rgba(255,107,139,.32)}

/* --- prompt helper v2 additions ------------------------------------------- */
.lx15-round{display:inline-block;font:700 11px/1 ui-sans-serif,system-ui;letter-spacing:.04em;
  color:#fdd7b5;background:rgba(246,164,92,.16);border:1px solid rgba(246,164,92,.34);
  border-radius:999px;padding:5px 10px;margin:0 0 9px}
.lx15-spin{display:inline-block;width:13px;height:13px;margin-right:7px;vertical-align:-2px;
  border:2px solid rgba(253,215,181,.28);border-top-color:#fdd7b5;border-radius:50%;
  animation:lx15-rot .8s linear infinite}
@keyframes lx15-rot{to{transform:rotate(360deg)}}
.lx15-retry{margin-left:8px;cursor:pointer;border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.05);
  color:#e4ddd6;border-radius:8px;padding:4px 10px;font:600 11.5px/1 ui-sans-serif,system-ui}
.lx15-retry:hover{background:rgba(246,164,92,.22);border-color:rgba(246,164,92,.5);color:#fff}
.lx15-adapt{margin:9px 0 0;font-size:11.5px;line-height:1.55;color:#a3988f}
.lx15-adapt b{color:#fdd7b5}
.lx15-adapt details{margin-top:5px}
.lx15-adapt summary{cursor:pointer;color:#c6bdb6}
.lx15-adapt ul{margin:6px 0 0;padding-left:18px}
.lx15-draft-restored{font-size:11.5px;color:#7ee0b4;margin:6px 0 0}

/* --- 18+ gate ------------------------------------------------------------- */
.lx15-nsfw-gate{margin:0 0 18px;padding:14px 16px;border-radius:14px;
  border:1px solid rgba(255,107,139,.3);background:rgba(255,107,139,.07);
  display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.lx15-nsfw-gate p{margin:0;flex:1 1 260px;font-size:12.5px;line-height:1.55;color:#d6cfc9}
.lx15-nsfw-gate b{color:#ff9db1}

@media (max-width:640px){
  .lx15-desk{padding:11px 12px;gap:10px}
  .lx15-desk .btn{flex:1 1 100%}
}
@media (prefers-reduced-motion:reduce){
  .lx15-spin{animation:none}
}

/* --- per-model icon tile --------------------------------------------------
   Replaces the bare favicon <img> the first v15 build put in the card: that
   left a white 42px square whenever Google's favicon service was slow, blocked
   or had nothing for the domain. The glyph comes from the model's class, so it
   always renders; the vendor favicon is a badge on top and removes itself on
   error. */
.lx15-ico{position:relative;background:linear-gradient(145deg,#3a2e24,#1f1a16);
  border:1px solid rgba(255,255,255,.1);overflow:visible}
.lx15-ico--big{width:50px;height:50px;border-radius:13px}
/* the maker's mark fills the tile; the class colour survives as the ring around it.
   Most brand marks are black on transparent, so they need a light plate to read
   on this theme - without it half the catalog would show an invisible logo. */
.lx15-ico__plate{position:absolute;inset:3px;border-radius:8px;background:#fff;
  display:flex;align-items:center;justify-content:center;overflow:hidden;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.07)}
.lx15-ico--big .lx15-ico__plate{inset:4px;border-radius:9px}
.lx15-ico__brand{width:76%;height:76%;object-fit:contain;display:block}
/* The white plate suits a dark mark on transparency - and only that. A favicon
   that already carries its own tile (Kling, Ideogram, Vidu) turned into a black
   square on it, and a white mark (Luma) disappeared into it. So the backdrop is
   chosen per logo from its measured pixels; see logo_plate.json. */
.lx15-ico__plate--bleed{inset:0;border-radius:11px;background:transparent}
.lx15-ico--big .lx15-ico__plate--bleed{border-radius:13px}
.lx15-ico__plate--bleed .lx15-ico__brand{width:100%;height:100%;object-fit:cover}
.lx15-ico__plate--dark{background:#1d1814;box-shadow:inset 0 0 0 1px rgba(255,255,255,.1)}
.lx15-ico__plate--mono{font:800 13px/1 ui-sans-serif,system-ui;color:#403327;letter-spacing:.01em}
.lx15-ico--big .lx15-ico__plate--mono{font-size:15px}
/* the class glyph still does its job - scanning the grid without reading a word -
   but as a corner badge now that the centre belongs to the brand */
.lx15-ico__cls{position:absolute;right:-5px;bottom:-5px;width:17px;height:17px;
  border-radius:50%;background:#1b1713;border:1px solid rgba(255,255,255,.16);
  display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,.5)}
.lx15-ico--big .lx15-ico__cls{width:19px;height:19px}
.lx15-ico__cls svg{width:11px;height:11px;fill:none;stroke:#fdd7b5;stroke-width:2.1;
  stroke-linecap:round;stroke-linejoin:round}
.lx15-ico--big .lx15-ico__cls svg{width:12px;height:12px}
/* one accent per class so the grid is scannable without reading a word */
.lx15-ico--photoreal{background:linear-gradient(145deg,rgba(56,189,248,.28),rgba(31,26,22,.95));
  border-color:rgba(56,189,248,.38)}
.lx15-ico--photoreal .lx15-ico__cls svg{stroke:#7dd3fc}
.lx15-ico--photoreal .lx15-ico__cls{border-color:#7dd3fc66}
.lx15-ico--creative{background:linear-gradient(145deg,rgba(244,114,182,.26),rgba(31,26,22,.95));
  border-color:rgba(244,114,182,.38)}
.lx15-ico--creative .lx15-ico__cls svg{stroke:#f9a8d4}
.lx15-ico--creative .lx15-ico__cls{border-color:#f9a8d466}
.lx15-ico--fast{background:linear-gradient(145deg,rgba(250,204,21,.26),rgba(31,26,22,.95));
  border-color:rgba(250,204,21,.38)}
.lx15-ico--fast .lx15-ico__cls svg{stroke:#fde047}
.lx15-ico--fast .lx15-ico__cls{border-color:#fde04766}
.lx15-ico--edit{background:linear-gradient(145deg,rgba(45,212,191,.26),rgba(31,26,22,.95));
  border-color:rgba(45,212,191,.38)}
.lx15-ico--edit .lx15-ico__cls svg{stroke:#5eead4}
.lx15-ico--edit .lx15-ico__cls{border-color:#5eead466}
.lx15-ico--flagship{background:linear-gradient(145deg,rgba(246,164,92,.32),rgba(31,26,22,.95));
  border-color:rgba(250,191,139,.45)}
.lx15-ico--flagship .lx15-ico__cls svg{stroke:#fdd7b5}
.lx15-ico--flagship .lx15-ico__cls{border-color:#c4b5fd66}
.lx15-ico--long{background:linear-gradient(145deg,rgba(129,140,248,.26),rgba(31,26,22,.95));
  border-color:rgba(129,140,248,.4)}
.lx15-ico--long .lx15-ico__cls svg{stroke:#a5b4fc}
.lx15-ico--long .lx15-ico__cls{border-color:#a5b4fc66}
.lx15-ico--reference{background:linear-gradient(145deg,rgba(52,211,153,.26),rgba(31,26,22,.95));
  border-color:rgba(52,211,153,.38)}
.lx15-ico--reference .lx15-ico__cls svg{stroke:#6ee7b7}
.lx15-ico--reference .lx15-ico__cls{border-color:#6ee7b766}
.lx15-ico--uncensored{background:linear-gradient(145deg,rgba(255,107,139,.26),rgba(31,26,22,.95));
  border-color:rgba(255,107,139,.4)}
.lx15-ico--uncensored .lx15-ico__cls svg{stroke:#ff9db1}
.lx15-ico--uncensored .lx15-ico__cls{border-color:#ff9db166}

/* the strongest single advantage, readable without hovering (and on touch) */
.lx15-card__lead{font:700 11.5px/1.35 ui-sans-serif,system-ui;color:#7ee0b4;
  display:flex;gap:5px;align-items:flex-start;margin:-2px 0 -2px}
.lx15-card__lead::before{content:"";flex:0 0 6px;height:6px;margin-top:4px;border-radius:50%;
  background:#3ad29f}

/* --- hover / focus tooltip ------------------------------------------------ */
.lx15-tip{position:fixed;z-index:9999;width:min(320px,calc(100vw - 16px));box-sizing:border-box;
  padding:14px 15px;border-radius:14px;background:#1b1713;
  border:1px solid rgba(250,191,139,.38);box-shadow:0 18px 44px rgba(0,0,0,.62);
  color:#f2ede8;pointer-events:none;opacity:0;transform:translateY(-4px);
  transition:opacity .13s ease,transform .13s ease}
.lx15-tip.is-on{opacity:1;transform:translateY(0)}
.lx15-tip[hidden]{display:none}
.lx15-tip__head{display:flex;gap:11px;align-items:center;margin-bottom:11px}
.lx15-tip__head .model-card__logo{width:38px;height:38px;border-radius:11px;flex-shrink:0;
  display:flex;align-items:center;justify-content:center}
.lx15-tip__id{min-width:0}
.lx15-tip__id b{display:block;font:750 14px/1.25 ui-sans-serif,system-ui;color:#fff}
.lx15-tip__id span{display:block;margin-top:2px;font-size:11.5px;color:#aea39a}
.lx15-tip__sum{margin:0 0 11px;font:400 12.5px/1.5 ui-sans-serif,system-ui;color:#dcd2c9;padding-bottom:10px;border-bottom:1px solid rgba(255,255,255,.07)}
.lx15-pros .lx15-tip__sum{color:#e0d7cf}
.lx15-tip__cap{font:800 9.5px/1 ui-sans-serif,system-ui;letter-spacing:.11em;text-transform:uppercase;
  color:#a3988f;margin-bottom:7px}
.lx15-tip__pros{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:6px}
.lx15-tip__pros li{position:relative;padding-left:19px;font-size:12.5px;line-height:1.4;color:#e8e2dc}
.lx15-tip__pros li::before{content:"";position:absolute;left:2px;top:4px;width:9px;height:5px;
  border-left:2px solid #3ad29f;border-bottom:2px solid #3ad29f;transform:rotate(-45deg)}
.lx15-tip__note{margin:11px 0 0;padding:8px 10px;border-radius:9px;font-size:11.5px;line-height:1.45;
  color:#f5b971;background:rgba(245,185,113,.1);border:1px solid rgba(245,185,113,.26)}
.lx15-tip__note b{color:#f5b971}
.lx15-tip__spec{margin:10px 0 0;font:600 11px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;
  color:#a3988f;overflow-wrap:anywhere}
.lx15-tip__cta{margin:9px 0 0;padding-top:8px;border-top:1px solid rgba(255,255,255,.08);
  font-size:11px;color:#a3988f}

/* same content inside the generation modal — touch never gets a hover */
.lx15-pros{margin:12px 0 2px}
.lx15-pros[hidden]{display:none}
.lx15-pros .lx15-tip__pros li{color:#e4ddd6}

@media (hover:none){
  .lx15-tip__cta{display:none}
}
@media (prefers-reduced-motion:reduce){
  .lx15-tip{transition:none;transform:none}
}

