<script>
var titles={"overview": "Overview", "videos": "Videos", "images": "Images", "usage": "Usage", "billing": "Credits & Billing", "referral": "Referral", "settings": "Settings", "creations": "My Creations"};
function setSec(s){
  if(!document.querySelector('.panel[data-panel="'+s+'"]'))s='overview';
  document.querySelectorAll('.nav[data-sec]').forEach(function(n){n.classList.toggle('on',n.dataset.sec===s);});
  document.querySelectorAll('.panel').forEach(function(p){p.classList.toggle('on',p.dataset.panel===s);});
  document.getElementById('secTitle').textContent=titles[s]||'';
  closeSb();window.scrollTo(0,0);
}
function openSb(){document.getElementById('sb').classList.add('open');document.getElementById('sbOv').classList.add('on');document.body.style.overflow='hidden';}
function closeSb(){document.getElementById('sb').classList.remove('open');document.getElementById('sbOv').classList.remove('on');document.body.style.overflow='';}
function toggleSb(){document.getElementById('sb').classList.contains('open')?closeSb():openSb();}
document.getElementById('sbOv').addEventListener('click',closeSb);
document.addEventListener('keydown',function(e){
  if(e.key!=='Escape')return;
  closeSb();
  document.querySelectorAll('.ov.on').forEach(function(o){closeModal(o.id);});
});
document.querySelectorAll('.nav[data-sec]').forEach(function(n){n.onclick=function(){setSec(n.dataset.sec);};});
var MODAL_LABEL={genModal:'genHeading',versionModal:'verFamName',genProgress:'lxpKind'};
var _modalReturn=null;
document.querySelectorAll('.ov').forEach(function(o){
  o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');
  if(MODAL_LABEL[o.id])o.setAttribute('aria-labelledby',MODAL_LABEL[o.id]);
});
function openModal(id){
  var o=document.getElementById(id);if(!o)return;
  _modalReturn=document.activeElement;
  o.classList.add('on');
  document.body.style.overflow='hidden';
  setTimeout(function(){
    if(!o.classList.contains('on'))return;
    var f=Array.prototype.filter.call(
      o.querySelectorAll('button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled])'),
      function(el){return el.offsetWidth||el.offsetHeight||el.getClientRects().length;})[0];
    if(f)try{f.focus({preventScroll:true});}catch(e){try{f.focus();}catch(e2){}}
  },30);
}
function closeModal(id){
  var o=document.getElementById(id);if(!o)return;
  o.classList.remove('on');
  /* the sidebar keeps its own lock, so only release when nothing else holds it */
  if(!document.querySelector('.ov.on')&&!document.getElementById('sb').classList.contains('open'))document.body.style.overflow='';
  if(_modalReturn&&_modalReturn.isConnected){try{_modalReturn.focus({preventScroll:true});}catch(e){}}
  _modalReturn=null;
}
/* keep Tab inside an open dialog */
document.addEventListener('keydown',function(e){
  if(e.key!=='Tab')return;
  var o=document.querySelector('.ov.on');if(!o)return;
  var f=Array.prototype.filter.call(
    o.querySelectorAll('button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])'),
    function(el){return el.offsetWidth||el.offsetHeight||el.getClientRects().length;});
  if(!f.length)return;
  var first=f[0],last=f[f.length-1];
  if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}
  else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
  else if(o.contains(document.activeElement)===false){e.preventDefault();first.focus();}
});
document.querySelectorAll('.ov').forEach(function(o){o.onclick=function(e){if(e.target===o)closeModal(o.id);};});
var _t;function toast(m){var t=document.getElementById('toast');t.textContent=m;t.classList.add('show');clearTimeout(_t);_t=setTimeout(function(){t.classList.remove('show');},2400);}
async function lxSaveUrl(u,label){if(!u){toast('Nothing to download yet');return;}var ext=(String(u).split('?')[0].split('.').pop()||'mp4').toLowerCase();if(!/^[a-z0-9]{2,4}$/.test(ext))ext='mp4';var base=String(label||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-+|-+$)/g,'')||'result';var name='neuravision-'+base+'-'+Date.now()+'.'+ext;toast('Preparing download…');try{var r=await fetch(u,{mode:'cors',cache:'no-store'});if(!r.ok)throw new Error('http '+r.status);var b=await r.blob();var obj=URL.createObjectURL(b);var a=document.createElement('a');a.href=obj;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(obj);},60000);toast('Download started');}catch(e){window.open(u,'_blank','noopener');toast('Opened the file in a new tab');}}
function copyText(id){
  var el=document.getElementById(id);
  el.select();el.setSelectionRange(0,99999);
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(el.value).catch(function(){});}
  else{document.execCommand('copy');}
  toast('Copied to clipboard');
}

/* ---- generation modal (core new function) ---- */
var currentTpl=null;
var currentSpec={a:1,b:1,aLabel:'',bLabel:''};

/* duration/quality/size option sets — multipliers scale the model's base (flagship) price.
   Video AI models carry their OWN real duration set (see data-durations, sourced from each
   vendor's docs); GENERIC_DURATION_OPTS is only the fallback for template cards that don't
   name a specific vendor model. */
var GENERIC_DURATION_OPTS=[{l:'4s',m:0.6},{l:'8s',m:1},{l:'12s',m:1.5}];
/* GENERIC_VIDEO_QUALITY_OPTS is only the fallback for template cards that don't name a
   specific vendor model — real AI models carry their OWN resolution set (data-qualities,
   sourced from each vendor's docs — most don't actually support 4K, see the QUAL_* table). */
var GENERIC_VIDEO_QUALITY_OPTS=[{l:'720p',m:0.8},{l:'1080p',m:1},{l:'4K',m:1.6}];
var IMAGE_SIZE_OPTS=[{l:'Square 1024²',m:1},{l:'Portrait 1024×1792',m:1.1},{l:'Landscape 1792×1024',m:1.1}];
var IMAGE_QUALITY_OPTS=[{l:'Standard',m:1},{l:'HD',m:1.6}];
/* "Our templates" / effect templates (lx-t-*, lx-fx-*, owner-*) run on the Neuravision
   Hybrid engine with no per-model duration control — duration is fixed by the template
   itself, only output quality is a real choice, at a flat credit price per tier. */
var HYBRID_TEMPLATE_QUALITY_OPTS=[{l:'720p',price:50},{l:'1080p',price:65},{l:'4K',price:100}];
function renderHybridQualityChips(containerId,defaultIdx,key){
  var el=document.getElementById(containerId);
  el.innerHTML=HYBRID_TEMPLATE_QUALITY_OPTS.map(function(o,i){
    return '<button type="button" class="chip'+(i===defaultIdx?' on':'')+'" onclick="pickHybridQuality(this,'+i+')">'+o.l+'</button>';
  }).join('');
  var o=HYBRID_TEMPLATE_QUALITY_OPTS[defaultIdx];
  currentSpec[key]=o.price;
  currentSpec[key+'Label']=o.l;
}
function pickHybridQuality(btn,idx){
  var row=btn.parentElement;
  row.querySelectorAll('.chip').forEach(function(c){c.classList.remove('on');});
  btn.classList.add('on');
  var o=HYBRID_TEMPLATE_QUALITY_OPTS[idx];
  currentSpec.b=o.price;
  currentSpec.bLabel=o.l;
  updatePrice();
}

function inferKind(data){
  if(data.type==='image')return 'image';
  if(data.type==='video')return 'video';
  return (data.badge&&data.badge.indexOf('Image')>-1)?'image':'video';
}
function renderChips(containerId,opts,defaultIdx,key){
  var el=document.getElementById(containerId);
  el.innerHTML=opts.map(function(o,i){
    return '<button type="button" class="chip'+(i===defaultIdx?' on':'')+'" onclick="pickSpec(this,\''+key+'\','+o.m+',\''+o.l+'\')">'+o.l+'</button>';
  }).join('');
  currentSpec[key]=opts[defaultIdx].m;
  currentSpec[key+'Label']=opts[defaultIdx].l;
}
function pickSpec(btn,key,mult,label){
  var row=btn.parentElement;
  row.querySelectorAll('.chip').forEach(function(c){c.classList.remove('on');});
  btn.classList.add('on');
  currentSpec[key]=mult;
  currentSpec[key+'Label']=label;
  updatePrice();
}
function updatePrice(){
  var p=currentTpl.isHybridTemplate?currentSpec.b:Math.max(1,Math.round(currentTpl.basePrice*currentSpec.a*currentSpec.b));
  currentTpl.price=p;
  document.getElementById('genGoBtn').textContent='Generate preview';
  document.getElementById('genTotal').textContent=p+' credits';
  document.getElementById('genPriceNote').textContent=(currentTpl.isHybridTemplate?currentSpec.bLabel:(currentSpec.aLabel+' · '+currentSpec.bLabel))+' · Demo estimate, no credits charged';
}
function openGenData(data){
  var promptOnly=!!data.promptOnly;
  var exact=data.versionSpec;
  var kind=inferKind(data);
  currentTpl={id:data.id,title:data.title,badge:data.badge,thumb:data.thumb||'',
              type:data.type,basePrice:data.price,price:data.price,promptOnly:promptOnly,logo:data.logo||'',kind:kind,modelId:data.modelId||'',versionSpec:data.versionSpec||null};
  document.getElementById('genTplTitle').textContent=currentTpl.title;
  document.getElementById('genTplBadge').textContent=currentTpl.badge;
  var prev=document.getElementById('genTplThumb');
  if(currentTpl.type==='model'){
    prev.style.background='#fff';
    prev.style.display='flex';prev.style.alignItems='center';prev.style.justifyContent='center';prev.style.fontSize='';
    prev.innerHTML='<img src="'+currentTpl.logo+'" style="width:34px;height:34px;object-fit:contain">';
  } else {
    prev.style.background='#000';prev.style.display='block';prev.style.fontSize='';
    prev.innerHTML=currentTpl.type==='video'?('<video data-lx-media-src="'+currentTpl.thumb+'" data-lx-autoplay="1" loop muted playsinline preload="none"></video>'):('<img src="'+currentTpl.thumb+'">');
  }
  resetVideoSource(data);
  document.getElementById('genDropzone').style.display=promptOnly?'none':'';
  document.getElementById('genPromptLabel').textContent=promptOnly?'Prompt':'Caption / instructions (optional)';
  document.getElementById('genPrompt').placeholder=promptOnly?'Describe exactly what you want to see… e.g. "A cinematic close-up portrait of an astronaut on Mars, golden hour light, 85mm lens"':'e.g. add slow zoom, warm color grade…';
  document.getElementById('genPrompt').value='';
  if(kind==='video'){
    currentTpl.isHybridTemplate=!exact&&!(data.durations&&data.durations.length);
    if(currentTpl.isHybridTemplate){
      document.getElementById('genRowA').style.display='none';
      currentSpec.a=1;currentSpec.aLabel='Auto';
      document.getElementById('genRowB').style.display='';
      document.getElementById('genRowBLabel').textContent='Quality';
      renderHybridQualityChips('genRowBChips',1,'b');
    } else {
      document.getElementById('genRowA').style.display='';
      document.getElementById('genRowALabel').textContent='Duration';
      document.getElementById('genRowBLabel').textContent='Quality';
      var durOpts=(data.durations&&data.durations.length)?data.durations.map(function(d){return{l:(d.s==='Auto'?'Auto':d.s+'s'),m:d.m};}):(exact?[{l:'Not specified',m:1}]:GENERIC_DURATION_OPTS);
      var durDefaultIdx=0;
      for(var di=0;di<durOpts.length;di++){if(durOpts[di].m===1){durDefaultIdx=di;break;}}
      renderChips('genRowAChips',durOpts,durDefaultIdx,'a');
      var qualOpts=(data.qualities&&data.qualities.length)?data.qualities:(exact?[{l:'Provider default',m:1}]:GENERIC_VIDEO_QUALITY_OPTS);
      var qualDefaultIdx=0;
      for(var qi=0;qi<qualOpts.length;qi++){if(qualOpts[qi].m===1){qualDefaultIdx=qi;break;}}
      renderChips('genRowBChips',qualOpts,qualDefaultIdx,'b');
    }
  } else {
    currentTpl.isHybridTemplate=false;
    document.getElementById('genRowA').style.display='';
    document.getElementById('genRowALabel').textContent='Size';
    document.getElementById('genRowBLabel').textContent='Quality';
    renderChips('genRowAChips',IMAGE_SIZE_OPTS,0,'a');
    renderChips('genRowBChips',IMAGE_QUALITY_OPTS,0,'b');
  }
  var info=document.getElementById('genModelInfo');
  info.textContent=exact ? exact.source+(exact.aspectRatios&&exact.aspectRatios.length?' · Ratios: '+exact.aspectRatios.join(' / '):'') : (currentTpl.isHybridTemplate ? 'Runs on Neuravision Hybrid · duration is fixed by the template, only output quality changes the price.' : 'Template demo settings · final options depend on the selected model.');
  if(exact && exact.verified===false)info.textContent+=' · Generation is unavailable until specifications are verified.';
  if(exact && exact.verified && !exact.qualities.length)info.textContent+=' · Output resolution is not specified in the catalog.';
  updatePrice();
  document.getElementById('genGoBtn').disabled=true;
  openModal('genModal');
}
function openGen(btn){
  openGenData({id:btn.dataset.id,title:btn.dataset.title,badge:btn.dataset.badge,thumb:btn.dataset.thumb,
               type:btn.dataset.type,price:parseInt(btn.dataset.price,10)||25,promptOnly:btn.dataset.promptOnly==='true'});
}

/* ---- model version picker ---- */
var currentFamily=null;
function openVersions(btn){
  currentFamily={id:btn.dataset.familyId,name:btn.dataset.familyName,logo:btn.dataset.logo,
                 badge:btn.dataset.badge,versions:JSON.parse(btn.dataset.versions.replace(/&#39;/g,"'")),
                 durations:btn.dataset.durations?JSON.parse(btn.dataset.durations.replace(/&#39;/g,"'")):null,
                 qualities:btn.dataset.qualities?JSON.parse(btn.dataset.qualities.replace(/&#39;/g,"'")):null};
  document.getElementById('verFamName').textContent=currentFamily.name;
  document.getElementById('verFamBadge').textContent=currentFamily.badge;
  document.getElementById('verFamLogo').src=currentFamily.logo;
  var list=document.getElementById('verList');
  list.innerHTML=currentFamily.versions.map(function(v,i){
    return '<button class="ver-row" type="button" onclick="selectVersion('+i+')">'+
      '<div class="ver-row__main"><div class="ver-row__label">'+v.label+'</div>'+
      '<div class="ver-row__desc">'+v.desc+'</div><span class="ver-spec">'+versionSummary(v)+'</span></div>'+
      '<span class="model-card__price">⚡ '+v.price+'</span></button>';
  }).join('');
  openModal('versionModal');
}
function selectVersion(i){
  var v=currentFamily.versions[i];
  closeModal('versionModal');
  var promptOnly=(currentFamily.badge==='Text → Video'||currentFamily.badge==='Text → Image');
  openGenData({id:currentFamily.id+'-v'+i,title:v.label,badge:currentFamily.badge,thumb:'',
               type:'model',price:v.price,promptOnly:promptOnly,logo:currentFamily.logo,
               durations:v.durations,qualities:v.qualities,modelId:v.modelId||'',versionSpec:v.verified===undefined?null:v});
}
var videoSource={mode:'file',file:null,url:'',ready:false,objectUrl:null};
function isVideoInput(){return currentTpl&&!currentTpl.promptOnly&&/Video → Video|Edit Text.*Video/i.test(currentTpl.badge||'');}
function clearSourcePreview(){
  var p=document.getElementById('genSourcePreview');
  p.onloadedmetadata=null;p.onerror=null;p.pause();p.removeAttribute('src');p.load();p.hidden=true;
  if(videoSource.objectUrl)URL.revokeObjectURL(videoSource.objectUrl);
  videoSource.objectUrl=null;videoSource.ready=false;
}
function resetVideoSource(data){
  clearSourcePreview();videoSource.mode='file';videoSource.file=null;videoSource.url='';
  document.getElementById('genFileInput').value='';
  document.getElementById('genVideoUrl').value='';
  document.getElementById('genUploadName').textContent='';
  document.getElementById('genSourceSwitch').style.display=isVideoInput()?'flex':'none';
  document.getElementById('genFileInput').accept=isVideoInput()?'video/mp4,video/webm,video/quicktime':'image/*,video/*';
  var dz=document.getElementById('genDropzone');
  dz.querySelector('div').textContent=isVideoInput()?'Drop your video here':'Drop your photo or video here';
  dz.querySelector('.muted').textContent=isVideoInput()?'or click to browse — MP4, WebM, MOV':'or click to browse — JPG, PNG, MP4';
  setVideoSource('file');
}
function setVideoSource(mode){
  clearSourcePreview();videoSource.mode=mode;videoSource.file=null;videoSource.url='';
  document.getElementById('genFileInput').value='';document.getElementById('genUploadName').textContent='';
  document.getElementById('genSourceStatus').textContent='';
  document.getElementById('genLinkPanel').hidden=mode!=='url';
  document.getElementById('genDropzone').style.display=mode==='url'||currentTpl.promptOnly?'none':'';
  ['file','url'].forEach(function(m){var el=document.getElementById(m==='file'?'genSourceFile':'genSourceLink');el.classList.toggle('on',m===mode);el.setAttribute('aria-pressed',String(m===mode));});
  updateSourceReady();
}
function updateSourceReady(){document.getElementById('genGoBtn').disabled=(currentTpl.versionSpec&&currentTpl.versionSpec.verified===false)|| (currentTpl.promptOnly?document.getElementById('genPrompt').value.trim().length<3:!videoSource.ready);}
function previewSource(src){
  var p=document.getElementById('genSourcePreview');p.hidden=false;
  document.getElementById('genSourceStatus').textContent='Loading video preview…';
  p.onloadedmetadata=function(){videoSource.ready=true;document.getElementById('genSourceStatus').textContent='✓ Video ready · '+p.videoWidth+' × '+p.videoHeight+(Number.isFinite(p.duration)?' · '+p.duration.toFixed(1)+' sec':'');updateSourceReady();};
  p.onerror=function(){videoSource.ready=false;document.getElementById('genSourceStatus').textContent='Cannot play this video. Check the direct link or upload a supported file.';updateSourceReady();};
  p.src=src;p.load();updateSourceReady();
}
function loadVideoLink(){
  clearSourcePreview();videoSource.url='';updateSourceReady();
  try{var u=new URL(document.getElementById('genVideoUrl').value.trim());
    if(u.protocol!=='https:'||u.username||u.password||/(^|\.)(youtube\.com|youtu\.be|tiktok\.com)$/i.test(u.hostname))throw Error();
    videoSource.url=u.href;previewSource(u.href);
  }catch(e){document.getElementById('genSourceStatus').textContent='Enter a direct HTTPS video link, without login credentials.';}
}
function pickFile(){document.getElementById('genFileInput').click();}
function acceptSourceFile(file){
  if(!file)return;clearSourcePreview();videoSource.file=null;updateSourceReady();
  if(isVideoInput()&&!/^video\/(mp4|webm|quicktime)$/.test(file.type)){
    document.getElementById('genUploadName').textContent='';
    document.getElementById('genSourceStatus').textContent='Choose an MP4, WebM or MOV video.';return;
  }
  videoSource.file=file;document.getElementById('genUploadName').textContent='✓ '+file.name;
  if(isVideoInput()){videoSource.objectUrl=URL.createObjectURL(file);previewSource(videoSource.objectUrl);}
  else{videoSource.ready=true;updateSourceReady();}
}
document.addEventListener('DOMContentLoaded',function(){
  document.getElementById('genFileInput').addEventListener('change',function(){acceptSourceFile(this.files[0]);});
  var dz=document.getElementById('genDropzone');
  dz.addEventListener('dragover',function(e){e.preventDefault();dz.classList.add('drag');});
  ['dragleave','drop'].forEach(function(ev){dz.addEventListener(ev,function(e){e.preventDefault();dz.classList.remove('drag');});});
  dz.addEventListener('drop',function(e){acceptSourceFile(e.dataTransfer.files[0]);});
  document.getElementById('genPrompt').addEventListener('input',updateSourceReady);
  document.getElementById('genVideoUrl').addEventListener('input',function(){clearSourcePreview();videoSource.url='';document.getElementById('genSourceStatus').textContent='';updateSourceReady();});
});
var HIST=JSON.parse(localStorage.getItem('lx_demo_hist')||'[]');
/* nothing finishes while the tab is closed: anything older than 2 minutes is done by now */
HIST.forEach(function(j){if(j&&j.status!=='done'&&Date.now()-(j.ts||0)>120000)j.status='done';});
function saveHist(){localStorage.setItem('lx_demo_hist',JSON.stringify(HIST));}
function startGenerate(){
  updateSourceReady();if(document.getElementById('genGoBtn').disabled)return;
  closeModal('genModal');
  var job={id:'job'+Date.now(),title:currentTpl.title,thumb:currentTpl.thumb,type:currentTpl.kind,
           logo:currentTpl.logo,status:'queued',ts:Date.now(),price:currentTpl.price,
           specLabel:currentSpec.aLabel+' · '+currentSpec.bLabel,prompt:document.getElementById('genPrompt').value};
  HIST.unshift(job);saveHist();
  toast('Web rendering is paused while we ship the new tools — open "'+currentTpl.title+'" in the desktop app.');
  renderHistory();
  setTimeout(function(){job.status='rendering';saveHist();renderHistory();},1800);
  setTimeout(function(){job.status='done';saveHist();renderHistory();toast('Your generation is ready 🎬');},4600);
}
function renderHistory(){
  var wrap=document.getElementById('histGrid');
  if(!wrap)return;
  if(!HIST.length){wrap.innerHTML='<div class="hist-empty">No generations yet — pick a template in Videos or Images to get started.</div>';return;}
  wrap.innerHTML=HIST.map(function(j){
    var badge=j.status==='queued'?'<span class="badge b-q">QUEUED</span>':j.status==='rendering'?'<span class="badge b-rend">RENDERING</span>':'<span class="badge b-done">DONE</span>';
    var mstyle='position:absolute;inset:0;width:100%;height:100%;object-fit:cover';
    var media='';
    if(j.status==='done'){
      if(j.thumb){media=j.type==='video'?('<video data-lx-media-src="'+j.thumb+'" data-lx-autoplay="1" loop muted playsinline style="'+mstyle+'" preload="none"></video>'):('<img src="'+j.thumb+'" style="'+mstyle+'">');}
      else{media='<div style="'+mstyle+';display:flex;align-items:center;justify-content:center;background:#fff"><img src="'+(j.logo||'')+'" style="width:32px;height:32px;object-fit:contain"></div>';}
    }
    return '<div class="vcard"><div class="vthumb">'+badge+media+'</div><div class="vbody"><div class="t">'+j.title+'</div>'+
      (j.specLabel?'<div class="hist-spec">'+j.specLabel+' · ⚡ '+j.price+'</div>':'')+'<div class="vacts">'+
      (j.status==='done'?'<button class="btn btn-ghost btn-sm" onclick="lxSaveUrl(\''+String(j.thumb||'').replace(/'/g,'')+'\',\''+String(j.title||'').replace(/'/g,'')+'\')">Download</button>':'<button class="btn btn-ghost btn-sm" disabled style="opacity:.4">Processing…</button>')+
      '</div></div></div>';
  }).join('');
}
renderHistory();

/* ---- favorites ---- */
var FAVS=JSON.parse(localStorage.getItem('lx_demo_favs')||'[]');
function toggleFav(e,id){
  e.stopPropagation();
  var i=FAVS.indexOf(id);
  if(i>-1)FAVS.splice(i,1);else FAVS.push(id);
  localStorage.setItem('lx_demo_favs',JSON.stringify(FAVS));
  document.querySelectorAll('.fav-btn[data-fav-id="'+id+'"]').forEach(function(b){b.classList.toggle('on',FAVS.indexOf(id)>-1);});
}
document.querySelectorAll('.fav-btn').forEach(function(b){if(FAVS.indexOf(b.dataset.favId)>-1)b.classList.add('on');});

/* ---- category pill filter (shared) ---- */
document.querySelectorAll('.img-cat[data-filter-cat]').forEach(function(p){
  p.onclick=function(){
    var group=p.closest('nav').id;
    document.querySelectorAll('#'+group+' .img-cat').forEach(function(x){x.style.borderColor='';x.style.background='';x.style.color='';});
    p.style.borderColor='rgba(250,191,139,.5)';p.style.background='#1c1814';p.style.color='#fff';
    var cat=p.dataset.filterCat;
    var sectionsWrap=document.getElementById(group.replace('Cats','Sections'));
    sectionsWrap.querySelectorAll('.img-section').forEach(function(s){
      s.style.display=(cat==='All'||s.dataset.sectionCat===cat)?'':'none';
    });
  };
});

/* ---- video model pipeline tabs ---- */
function showPipeline(btn,pipe){
  var group=btn.parentElement;
  group.querySelectorAll('.pipeline-tab').forEach(function(b){b.classList.remove('on');});
  btn.classList.add('on');
  group.querySelectorAll('.pipeline-tab').forEach(function(b){b.setAttribute('aria-pressed',b===btn?'true':'false');});
  var section=group.parentElement;
  section.querySelectorAll('[data-pipe-panel]').forEach(function(p){p.style.display=(p.dataset.pipePanel===pipe)?'':'none';});
}

/* ---- search + sort (variants with search enabled) ---- */
function filterCatalog(prefix){
  var se=document.getElementById(prefix+'Search'),so=document.getElementById(prefix+'Sort'),wrap=document.getElementById(prefix+'Sections');
  if(!se||!so||!wrap)return;
  var q=(se.value||'').toLowerCase();
  var sort=so.value;
  wrap.querySelectorAll('.img-product').forEach(function(btn){
    var match=btn.dataset.title.toLowerCase().indexOf(q)>-1;
    btn.style.display=match?'':'none';
  });
  wrap.querySelectorAll('.img-products').forEach(function(grid){
    var cards=Array.prototype.slice.call(grid.children);
    /* remember the authored order once, so "Popular" can come back to it */
    cards.forEach(function(c,i){if(c.dataset.ord===undefined)c.dataset.ord=i;});
    if(sort==='az')cards.sort(function(a,b){return a.dataset.title.localeCompare(b.dataset.title);});
    else cards.sort(function(a,b){return a.dataset.ord-b.dataset.ord;});
    cards.forEach(function(c){grid.appendChild(c);});
  });
  var panel=wrap.closest('.panel');
  if(panel){
    panel.querySelectorAll('.model-card').forEach(function(m){
      var name=(m.dataset.familyName||'').toLowerCase();
      m.style.display=(!q||name.indexOf(q)>-1)?'':'none';
    });
  }
}
</script>
</div></div><script>
function versionSummary(v){
 if(v.verified===undefined)return '';
 if(!v.verified)return 'Specifications pending · unavailable';
 var ds=(v.durations||[]).map(function(d){return d.s==='Auto'?'Auto':d.s+'s';});
 var qs=(v.qualities||[]).map(function(q){return q.l;});
 return (ds.length>6?ds[0]+'–'+ds[ds.length-1]:ds.join(' / '))+' · '+(qs.length?qs.join(' / '):'Resolution not specified');
}
setSec('overview');
</script><script>(function(){
'use strict';
const $=id=>document.getElementById(id);
let controller=null,revision=0,questions=[],history=[],round=0,busy=false;
function status(text,error=false){$('paStatus').textContent=text;$('paStatus').classList.toggle('pa-error',error);}
function lockAnswers(locked){$('paQuestionList').querySelectorAll('button,textarea').forEach(el=>el.disabled=locked);}
function stop(){lockAnswers(false);revision++;if(controller)controller.abort();controller=null;busy=false;['paAnalyze','paCompose'].forEach(id=>$(id).disabled=false);}
function invalidate(){stop();questions=[];history=[];round=0;$('paQuestions').hidden=true;$('paResult').hidden=true;status('');}
function reset(){invalidate();$('paIdea').value='';$('paDraft').value='';$('paPanel').hidden=true;$('paToggle').setAttribute('aria-expanded','false');}
const openOriginal=window.openGenData;
window.openGenData=function(data){reset();return openOriginal(data);};
const closeOriginal=window.closeModal;
window.closeModal=function(id){if(id==='genModal'&&busy){stop();status('Request cancelled. You can try again.');}return closeOriginal(id);};
$('paToggle').onclick=()=>{const show=$('paPanel').hidden;$('paPanel').hidden=!show;$('paToggle').setAttribute('aria-expanded',String(show));if(show){if(!$('paIdea').value)$('paIdea').value=$('genPrompt').value;$('paIdea').focus();}};
$('paIdea').addEventListener('input',invalidate);
$('genSpecs').addEventListener('click',()=>{if(!$('paPanel').hidden){invalidate();status('Settings changed — refine the idea again so the assistant uses the new parameters.');}});
function context(){return {selectionType:currentTpl.type,title:currentTpl.type==='model'?'':currentTpl.title,badge:currentTpl.badge,kind:currentTpl.kind,durationOrSize:currentSpec.aLabel,quality:currentSpec.bLabel,source:currentTpl.promptOnly?'No source file':'A source file is provided; the assistant cannot see its contents'};}
function render(data){
 status(data.summary);questions=data.questions;$('paQuestions').hidden=!questions.length;$('paResult').hidden=!!questions.length;
 $('paQuestionList').replaceChildren();
 questions.forEach((q,i)=>{const wrap=document.createElement('div');wrap.className='pa-question';const label=document.createElement('label');label.htmlFor='paAnswer'+i;label.textContent=(i+1)+'. '+q.question;wrap.append(label);
 const opts=document.createElement('div');opts.className='pa-options';const answer=document.createElement('textarea');answer.id='paAnswer'+i;answer.rows=2;answer.maxLength=450;answer.placeholder='Your answer, or leave it to the assistant';
 q.options.forEach(o=>{const b=document.createElement('button');b.type='button';b.textContent=o;b.setAttribute('aria-pressed','false');b.onclick=()=>{answer.value=o;opts.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));};opts.append(b);});
 answer.oninput=()=>opts.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed','false'));wrap.append(opts,answer);$('paQuestionList').append(wrap);});
 if(!questions.length){$('paDraft').value=data.prompt;$('paAssumptions').textContent=data.assumptions.length?'The assistant assumed: '+data.assumptions.join(' • '):'Prompt composed from your instructions.';}
}
async function request(action){
 if(busy)return;const idea=$('paIdea').value.trim();if(idea.length<3){status('Describe your idea in at least a few words.',true);$('paIdea').focus();return;}
 const answers=action==='compose'?history.concat(questions.map((q,i)=>({question:q.question,answer:$('paAnswer'+i).value.trim()}))):[];
 const nextRound=action==='compose'?round+1:0;
 stop();const rev=revision;controller=new AbortController();const signal=controller.signal;busy=true;lockAnswers(true);['paAnalyze','paCompose'].forEach(id=>$(id).disabled=true);$('paResult').hidden=true;status(action==='analyze'?'Analysing your idea…':'Composing your prompt…');
 const timeout=setTimeout(()=>controller&&controller.abort(),55000);
 try{
  const init=await fetch('/lk/pa.php',{credentials:'same-origin',signal});if(!init.ok)throw Error('Could not reach the assistant. Please try again.');const auth=await init.json();
  const response=await fetch('/lk/pa.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':auth.token},body:JSON.stringify({action,idea,context:context(),answers,latestAnswerCount:action==='compose'?questions.length:0,round:Math.max(1,nextRound)}),signal});
  let data;try{data=await response.json();}catch(e){throw Error('No response from the server. Please try again.');}if(!response.ok)throw Error(data.error||'The assistant is unavailable. Please try again.');
  if(rev!==revision)return;history=answers;round=nextRound;render(data);
 }catch(e){if(rev===revision)status(e.name==='AbortError'?'That took too long. Please try again.':e.message,true);}
 finally{clearTimeout(timeout);if(rev===revision){busy=false;controller=null;lockAnswers(false);['paAnalyze','paCompose'].forEach(id=>$(id).disabled=false);}}
}
$('paAnalyze').onclick=()=>request('analyze');$('paCompose').onclick=()=>request('compose');
$('paApply').onclick=()=>{const text=$('paDraft').value.trim();if(!text){status('The prompt is empty. Write something or compose it again.',true);return;}$('genPrompt').value=text;$('genPrompt').dispatchEvent(new Event('input',{bubbles:true}));status('Prompt copied into the request field. Review it before you generate.');$('genPrompt').focus();};
})();
</script><script id="v14js">/* ===== Neuravision Studio v14 — runtime layer ==============================
   Loaded after the original script. Wraps, never forks, the v7 functions. */
(function(){
'use strict';
var $=function(id){return document.getElementById(id);};
var RATE=0.019;                      /* 1 credit ≈ $0.019 — matches Starter: $19 / 1,000 credits */

/* ---------- money ----------------------------------------------------- */
function usd(c){var v=c*RATE;return '$'+(v<10?v.toFixed(2):v.toFixed(0));}
function moneyNote(text){
  var nums=(text.match(/\d+/g)||[]).map(Number);
  if(!nums.length)return '';
  return nums.length>1?('≈ '+usd(nums[0])+'–'+usd(nums[nums.length-1])):('≈ '+usd(nums[0]));
}
function annotatePrices(root){
  (root||document).querySelectorAll('.model-card__price,.ver-row .model-card__price').forEach(function(el){
    if(el.querySelector('.usd'))return;
    var n=moneyNote(el.textContent);if(!n)return;
    var sm=document.createElement('small');sm.className='usd';sm.textContent=n;el.appendChild(sm);
  });
}

/* ---------- monogram marks ------------------------------------------- */
function esc14(x){return String(x==null?'':x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function mono(name){
  name=(name||'').trim();
  var p=name.split(/[\s\-–]+/).filter(Boolean);
  return (p.length>1?(p[0][0]+p[1][0]):name.slice(0,2)).toUpperCase();
}
function monoBox(name,size){
  return '<span class="mono'+(size?' lg':'')+'" style="width:100%;height:100%;border-radius:inherit">'+mono(name)+'</span>';
}

/* ---------- swap the version-modal logo for a monogram ---------------- */
(function(){
  var img=$('verFamLogo');if(!img||img.tagName!=='IMG')return;
  var span=document.createElement('span');
  span.id='verFamLogo';span.className='mono lg';
  span.style.cssText='width:44px;height:44px;flex-shrink:0;border:1px solid rgba(255,255,255,.08)';
  img.parentNode.replaceChild(span,img);
})();

var _openVersions=window.openVersions;
window.openVersions=function(btn){
  _openVersions(btn);
  var el=$('verFamLogo');
  if(el&&el.tagName==='SPAN')el.textContent=btn.dataset.mono||mono(btn.dataset.familyName);
  annotatePrices($('verList'));
};

var _openGenData=window.openGenData;
window.openGenData=function(data){
  var r=_openGenData(data);
  if(data.type==='model'){
    var prev=$('genTplThumb');
    prev.style.background='transparent';
    prev.innerHTML=monoBox(data.title,true);
  }
  return r;
};

var _updatePrice=window.updatePrice;
window.updatePrice=function(){
  _updatePrice();
  var t=$('genTotal');
  t.innerHTML=currentTpl.price+' credits <small class="usd" style="display:inline;margin-left:6px">'+
              moneyNote(String(currentTpl.price))+'</small>';
  $('genGoBtn').textContent='Generate — '+currentTpl.price+' ⚡';
};

/* ---------- quick filters -------------------------------------------- */
var LX={chip:'all',cat:'All'};
function cardPrice(b){return parseInt(b.dataset.price,10)||0;}
function chipOK(b){
  if(LX.chip==='all')return true;
  if(LX.chip==='cheap')return cardPrice(b)>0&&cardPrice(b)<25;
  if(LX.chip==='fav')return FAVS.indexOf(b.querySelector('.fav-btn')?b.querySelector('.fav-btn').dataset.favId:'')>-1;
  return (b.dataset.badge||'')===LX.chip;
}
function lxApply(){
  var wrap=$('vidSections');if(!wrap)return;
  var q=(($('vidSearch')||{}).value||'').toLowerCase().trim();
  wrap.querySelectorAll('.img-section').forEach(function(sec){
    var catOK=(LX.cat==='All'||sec.dataset.sectionCat===LX.cat),any=0;
    sec.querySelectorAll('.img-product').forEach(function(b){
      var ok=catOK&&chipOK(b)&&(!q||b.dataset.title.toLowerCase().indexOf(q)>-1);
      b.style.display=ok?'':'none';if(ok)any++;
    });
    sec.style.display=(catOK&&any)?'':'none';
  });
  var empty=$('vidNoResults');
  var total=wrap.querySelectorAll('.img-product:not([style*="none"])').length;
  if(empty)empty.style.display=total?'none':'';
}
var _filterCatalog=window.filterCatalog;
window.filterCatalog=function(prefix){_filterCatalog(prefix);if(prefix==='vid')lxApply();};

document.querySelectorAll('#vidChips .qchip').forEach(function(c){
  c.addEventListener('click',function(){
    document.querySelectorAll('#vidChips .qchip').forEach(function(x){x.classList.remove('on');});
    c.classList.add('on');LX.chip=c.dataset.q;lxApply();
  });
});
document.querySelectorAll('#vidCats .img-cat').forEach(function(p){
  p.addEventListener('click',function(){LX.cat=p.dataset.filterCat;setTimeout(lxApply,0);});
});
/* no-results state for the catalog */
(function(){
  var wrap=$('vidSections');if(!wrap)return;
  var d=document.createElement('div');d.id='vidNoResults';d.className='empty';d.style.display='none';
  d.innerHTML='<div class="empty__ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5" stroke-linecap="round"/></svg></div>'+
    '<h3>Nothing matches that yet</h3><p>Try a shorter word, or clear the filters to see all 150 scenes.</p>'+
    '<button class="btn btn-ghost btn-sm" id="vidReset" type="button">Clear filters</button>';
  wrap.appendChild(d);
  d.querySelector('#vidReset').onclick=function(){
    if($('vidSearch'))$('vidSearch').value='';
    LX.chip='all';LX.cat='All';
    document.querySelectorAll('#vidChips .qchip').forEach(function(x){x.classList.toggle('on',x.dataset.q==='all');});
    document.querySelectorAll('#vidCats .img-cat').forEach(function(x){
      var isAll=x.dataset.filterCat==='All';
      x.style.borderColor=isAll?'rgba(250,191,139,.5)':'';x.style.background=isAll?'#1c1814':'';x.style.color=isAll?'#fff':'';
    });
    lxApply();
  };
})();

/* ---------- favorites panel ------------------------------------------ */
if(window.titles)titles.favorites='Favorites';
function renderFavs(){
  var grid=$('favGrid');if(!grid)return;
  grid.innerHTML='';
  var made=0;
  FAVS.forEach(function(id){
    var btn=document.querySelector('#vidSections .fav-btn[data-fav-id="'+id+'"]');
    if(!btn)return;
    var card=btn.closest('.img-product');if(!card)return;
    var clone=card.cloneNode(true);clone.style.display='';
    clone.querySelectorAll('.fav-btn').forEach(function(f){f.classList.add('on');});
    grid.appendChild(clone);made++;
  });
  if(!made){
    grid.innerHTML='<div class="empty" style="grid-column:1/-1"><div class="empty__ico">'+
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 8.25c0-2.485-2.099-4.5-4.688-4.5-1.935 0-3.597 1.126-4.312 2.733-.715-1.607-2.377-2.733-4.313-2.733C5.1 3.75 3 5.765 3 8.25c0 7.22 9 12 9 12s9-4.78 9-12z" stroke-linecap="round" stroke-linejoin="round"/></svg></div>'+
      '<h3>No favorites yet</h3><p>Tap the heart on any scene in the catalog and it will wait for you here.</p>'+
      '<button class="btn btn-pri btn-sm" onclick="setSec(\'videos\')" type="button">Browse the catalog →</button></div>';
  }
  var c=$('favCount');if(c)c.textContent=FAVS.length?String(FAVS.length):'';
  var ov=$('ovFavCount');if(ov)ov.textContent=String(FAVS.length);
}
var _toggleFav=window.toggleFav;
window.toggleFav=function(e,id){_toggleFav(e,id);renderFavs();if(LX.chip==='fav')lxApply();};

/* ---------- history: richer cards, real empty state, reward ---------- */
var NEW_ID=null;
function cardHTML(j){
  var badge=j.status==='queued'?'<span class="badge b-q">QUEUED</span>':
            j.status==='rendering'?'<span class="badge b-rend">RENDERING</span>':
            '<span class="badge b-done">DONE</span>';
  var ms='position:absolute;inset:0;width:100%;height:100%;object-fit:cover';
  var media='';
  if(j.status==='done'){
    if(j.thumb){media=j.type==='video'
      ?'<video data-lx-media-src="'+j.thumb+'" data-lx-autoplay="1" loop muted playsinline style="'+ms+'" preload="none"></video>'
      :'<img src="'+j.thumb+'" style="'+ms+'">';}
    else{media='<div style="'+ms+';display:flex;align-items:center;justify-content:center;background:linear-gradient(160deg,#302216,#191410)">'+monoBox(j.title,true)+'</div>';}
  }
  var acts=j.status==='done'
    ?'<button class="btn btn-ghost btn-sm" onclick="lxSaveUrl(&quot;'+esc14(String(j.thumb||'').replace(/["\\]/g,''))+'&quot;,&quot;'+esc14(String(j.title||'').replace(/["\\]/g,''))+'&quot;)" type="button">Download</button>'
    :'<button class="btn btn-ghost btn-sm" disabled style="opacity:.4" type="button">Processing…</button>';
  return '<div class="vcard'+(j.id===NEW_ID&&j.status==='done'?' is-new':'')+'"><div class="vthumb">'+badge+media+'</div>'+
    '<div class="vbody"><div class="t">'+esc14(j.title)+'</div>'+
    (j.specLabel?'<div class="hist-spec">'+esc14(j.specLabel)+' · ⚡ '+j.price+' · '+moneyNote(String(j.price))+'</div>':'')+
    '<div class="vacts">'+acts+'</div></div></div>';
}
window.renderHistory=function(){
  var wrap=$('histGrid');
  if(wrap){
    if(!HIST.length){
      wrap.innerHTML='<div class="hist-empty empty" style="grid-column:1/-1"><div class="empty__ico">'+
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="5" width="13" height="14" rx="3"/><path d="M16 10.5l5-3v9l-5-3z" stroke-linejoin="round"/></svg></div>'+
        '<h3>Your library is empty — for about a minute</h3>'+
        '<p>Pick a scene, drop in a photo and generate. Everything you make lands here, ready to download.</p>'+
        '<button class="btn btn-pri btn-sm" onclick="setSec(\'videos\')" type="button">Pick a scene →</button></div>';
    } else {
      wrap.innerHTML=HIST.map(cardHTML).join('');
    }
  }
  renderOverview();
};

/* ---------- overview -------------------------------------------------- */
function renderOverview(){
  var c=$('ovCount');if(c)c.textContent=String(HIST.length);
  var f=$('ovFavCount');if(f)f.textContent=String(FAVS.length);
  var rec=$('ovRecent');
  if(rec)rec.innerHTML=HIST.length?HIST.slice(0,3).map(cardHTML).join('')
    :'<div class="empty" style="grid-column:1/-1"><h3>Nothing here yet</h3><p>Your finished clips will appear in this row.</p></div>';
  var res=$('ovResume');
  if(res){
    var j=HIST[0];
    if(j){
      var thumb=j.thumb
        ?(j.type==='video'?'<video data-lx-media-src="'+j.thumb+'" data-lx-autoplay="1" loop muted playsinline preload="none"></video>':'<img src="'+j.thumb+'">')
        :monoBox(j.title,true);
      res.innerHTML='<div class="resume__thumb">'+thumb+'</div><div class="resume__body">'+
        '<div class="eyebrow">Pick up where you left off</div>'+
        '<div style="font-weight:700;font-size:16px;margin-bottom:4px">'+esc14(j.title)+'</div>'+
        '<div class="muted" style="font-size:13px">'+esc14(j.specLabel||'')+' · '+
        (j.status==='done'?'ready to download':'still rendering')+'</div></div>'+
        '<button class="btn btn-pri" onclick="setSec(\'creations\')" type="button">Open →</button>';
    } else {
      res.innerHTML='<div class="resume__body"><div class="eyebrow">Start here</div>'+
        '<div style="font-weight:700;font-size:16px;margin-bottom:4px">Turn a photo into a moving shot</div>'+
        '<div class="muted" style="font-size:13px">Choose a scene, drop your photo in, and the model does the rest — about a minute for a 5-second clip.</div></div>'+
        '<button class="btn btn-pri" onclick="setSec(\'videos\')" type="button">Browse 150 scenes →</button>';
    }
  }
}
function fillPicks(){
  var grid=$('ovPicks');if(!grid||grid.children.length)return;
  var src=document.querySelectorAll('#our-templates .img-product');
  if(!src.length)src=document.querySelectorAll('#vidSections .img-product');
  Array.prototype.slice.call(src,0,4).forEach(function(card){
    var clone=card.cloneNode(true);clone.style.display='';grid.appendChild(clone);
  });
}

/* ---------- progress screen ------------------------------------------ */
var P={timer:null,job:null,expected:60,started:0,done:false};
function clock(s){var m=Math.floor(s/60),x=Math.floor(s%60);
  return (m<10?'0':'')+m+':'+(x<10?'0':'')+x;}
function durationSeconds(){
  var lbl=(currentSpec&&currentSpec.aLabel)||'';
  var m=lbl.match(/(\d+)\s*s/i);
  if(m)return parseInt(m[1],10);
  if(currentTpl&&currentTpl.kind==='image')return 0;
  return 5;
}
function lxTick(){
  if(P.done)return;
  var el=Math.max(0,(Date.now()-P.started)/1000);
  var pct=Math.min(99,Math.floor(el/P.expected*100));
  $('lxpPercent').textContent=pct+'%';
  var fill=document.querySelector('#genProgress .fill');
  fill.style.width=pct+'%';
  document.querySelector('#genProgress .meter').setAttribute('aria-valuenow',pct);
  $('lxpElapsed').textContent=clock(el);
  $('lxpRemaining').textContent=el>=P.expected?'finishing up':'≈ '+clock(Math.ceil(P.expected-el))+' left';
  $('lxpStatus').textContent=el>=P.expected?'Almost there — waiting for the final frames.':'';
  if(P.job&&P.job.status==='queued'&&el>3){P.job.status='rendering';saveHist();renderHistory();}
  if(el>=P.expected+6)lxFinish();
}
function lxFinish(){
  if(P.done)return;
  P.done=true;clearInterval(P.timer);
  $('lxpPercent').textContent='100%';
  document.querySelector('#genProgress .fill').style.width='100%';
  if(P.job){
    P.job.status='done';saveHist();NEW_ID=P.job.id;renderHistory();
    setTimeout(function(){NEW_ID=null;},2600);
  }
  setTimeout(function(){
    /* a job the user pushed to the background only gets the toast, not a jump */
    if(!P.bg){closeModal('genProgress');setSec('creations');}
    toast('Ready — "'+(P.job?P.job.title:'your clip')+'" is in your library');
  },450);
}
function lxStart(job){
  /* the previous job loses its timer here, so close it out instead of leaving it stuck */
  if(P.job&&P.job.status!=='done'){P.job.status='done';saveHist();renderHistory();}
  P.job=job;P.done=false;P.bg=false;P.started=Date.now();
  var secs=durationSeconds();
  var isImage=currentTpl&&currentTpl.kind==='image';
  P.expected=isImage?20:Math.max(30,secs*12);
  var mins=P.expected/60;
  $('lxpEstimate').textContent=isImage?'20 seconds'
    :(mins===1?'1 minute':(mins%1?mins.toFixed(1):mins)+' minutes');
  $('lxpKind').textContent=isImage?'Generating image':'Generating video';
  $('lxpMeta').innerHTML=[
    job.title,
    isImage?'image':(secs+'s clip'),
    (currentSpec.bLabel||''),
    '⚡ '+job.price+' · '+moneyNote(String(job.price))
  ].filter(Boolean).map(function(x){return '<span>'+x+'</span>';}).join('');
  $('lxpStatus').textContent='';
  document.querySelector('#genProgress .fill').style.width='0%';
  openModal('genProgress');
  clearInterval(P.timer);P.timer=setInterval(lxTick,250);lxTick();
}
$('lxpSkip').onclick=lxFinish;
$('lxpBg').onclick=function(){
  P.bg=true;
  closeModal('genProgress');
  toast('Running in the background — we will ping you when it is ready');
};
document.addEventListener('visibilitychange',function(){if(!P.done)lxTick();});

window.startGenerate=function(){
  updateSourceReady();
  if($('genGoBtn').disabled)return;
  var job={id:'job'+Date.now(),title:currentTpl.title,thumb:currentTpl.thumb,type:currentTpl.kind,
           logo:currentTpl.logo,status:'queued',ts:Date.now(),price:currentTpl.price,
           specLabel:currentSpec.aLabel+' · '+currentSpec.bLabel,prompt:$('genPrompt').value};
  HIST.unshift(job);saveHist();renderHistory();
  closeModal('genModal');
  lxStart(job);
};

/* ---------- boot ------------------------------------------------------ */
annotatePrices(document);
/* Demo dates are derived from today, so the billing panel never shows a past renewal. */
(function(){
  var n=new Date(), nx=new Date(n.getFullYear(),n.getMonth()+1,1),
      f=function(d){return d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});},
      dd=Math.max(1,Math.round((nx-n)/864e5));
  if($('billRenew'))$('billRenew').textContent='Renews '+f(nx)+' \u00b7 Visa \u2022\u2022\u2022\u2022 4242';
  if($('usgReset'))$('usgReset').textContent='resets in '+dd+' day'+(dd===1?'':'s');
  if($('billRow1Date'))$('billRow1Date').textContent=f(new Date(n.getFullYear(),n.getMonth(),1));
})();
fillPicks();
renderFavs();
renderHistory();
lxApply();
})();
</script><script src="/lk/assets-b/assistant-core.js"></script>
<script id="lx15js">
/* ===== Neuravision Studio v15 — runtime layer ==================================
   Loaded LAST, after the v7 script and the v14 runtime layer.
   It wraps and overrides; it never forks the earlier code.

   Adds, in this order:
     1. i18n with real auto-detection (navigator.languages), manual override wins
     2. the live Venice model catalog from model-profiles.json
     3. an opt-in negative-prompt field that follows the selected model
     4. prompt assistant v2: intent in, model-specific prompt out
     5. the desktop-app block the owner asked for
   ======================================================================== */
(function () {
  'use strict';
  var $ = function (id) { return document.getElementById(id); };
  var LS_LANG = 'lx15.lang';
  var SS_DRAFT = 'lx15.draft';
  var SS_NSFW = 'lx15.nsfw';

  /* =====================================================================
     1. i18n
     ===================================================================== */
  var DICT = {
    ru: {
      langLabel: 'Язык',
      deskKick: 'Также доступно',
      deskTitle: 'У Neuravision есть десктопное приложение',
      deskText: 'Кроме этого личного кабинета в браузере у нас есть отдельное приложение для компьютера. Оно работает с теми же моделями и вашим аккаунтом, но не зависит от вкладки браузера: очередь генераций продолжает идти, даже если закрыть сайт, а готовые файлы сохраняются сразу на диск.',
      deskL1: 'Windows и macOS',
      deskL2: 'Очередь работает в фоне',
      deskL3: 'Файлы сразу на диск',
      deskL4: 'Тот же аккаунт и те же модели',
      deskCta: 'Получить ссылку на приложение',
      deskMiniTitle: 'Есть приложение для компьютера',
