  var LANG = 'en';
  function detectLang() {
    /* 2026-10-10 owner: the cabinet follows the SITE language (9 langs, cookie lx-language,
       translated by nv_i18n from English). Russian is not a site language -> always 'en'. */
    if (window.nvI18n || document.documentElement.hasAttribute('data-nv-lang')) return 'en';
    var saved = null;
    try { saved = localStorage.getItem(LS_LANG); } catch (e) {}
    if (saved && DICT[saved]) return saved;                 // manual choice wins forever
    var list = (navigator.languages && navigator.languages.length)
      ? navigator.languages : [navigator.language || 'en'];
    for (var i = 0; i < list.length; i++) {
      var base = String(list[i] || '').toLowerCase().split('-')[0];
      if (DICT[base]) return base;
    }
    return 'en';                                            // documented fallback
  }
  function t(key, a) {
    var s = (DICT[LANG] && DICT[LANG][key]) || DICT.en[key] || key;
    return a === undefined ? s : s.replace('%1', a);
  }
  /** Translate one subtree. Safe to call from a re-render; fires no events. */
  function applyLangIn(root) {
    (root || document).querySelectorAll('[data-lx15-t]').forEach(function (el) {
      var k = el.getAttribute('data-lx15-t');
      if (el.getAttribute('data-lx15-html') === '1') el.innerHTML = t(k);
      else el.textContent = t(k);
    });
    (root || document).querySelectorAll('[data-lx15-ph]').forEach(function (el) {
      el.setAttribute('placeholder', t(el.getAttribute('data-lx15-ph')));
    });
  }

  /* Announce a language change exactly once. An earlier revision called
     applyLang() from inside a catalog re-render, whose own listener re-rendered
     again — the page hung in that loop. Rendering now uses applyLangIn(). */
  function applyLang() {
    if (LANG === 'ru' || !document.documentElement.hasAttribute('data-nv-lang')) document.documentElement.setAttribute('lang', LANG); /* nv_i18n-lang-guard */
    applyLangIn(document);
    document.querySelectorAll('.lx15-lang button').forEach(function (b) {
      b.setAttribute('aria-pressed', String(b.getAttribute('data-lang') === LANG));
    });
    document.dispatchEvent(new CustomEvent('lx15:lang', { detail: { lang: LANG } }));
  }
  function setLang(l) {
    if (!DICT[l]) return;
    LANG = l;
    try { localStorage.setItem(LS_LANG, l); } catch (e) {}
    applyLang();
  }
  LANG = detectLang();

  /* =====================================================================
     2. model profiles (live Venice catalog)
     ===================================================================== */
  var PROFILES = { image: [], video: [], classes: {}, negative_preset_library: { ru: [], en: [] } };
  var byId = {};
  var profilesReady = fetch('/lk/assets-b/model-profiles.json', { credentials: 'same-origin' })
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (d) {
      if (!d) return;
      PROFILES = d;
      (d.image || []).concat(d.video || []).forEach(function (m) { byId[m.id] = m; });
    })
    .catch(function () { /* the studio must still work without the registry */ });

  function profileOf(id) { return byId[id] || null; }

  /* Best-effort match from a legacy V14 card title to a real Venice model,
     so the profile strip and the negative field behave there too. */
  function guessProfile(title, kind) {
    if (!title) return null;
    var norm = String(title).toLowerCase().replace(/[^a-z0-9]+/g, '');
    var pool = (kind === 'video' ? PROFILES.video : PROFILES.image) || [];
    var best = null, bestLen = 0;
    pool.forEach(function (m) {
      var n = String(m.name).toLowerCase().replace(/[^a-z0-9]+/g, '');
      if (n === norm && n.length > bestLen) { best = m; bestLen = n.length; }
    });
    return best;
  }

  /* =====================================================================
     3. sidebar: language switcher + desktop note
     ===================================================================== */
  function buildSidebar() {
    var sb = $('sb');
    if (!sb) return;
    var anchor = sb.querySelector('.lg');
    var lang = document.createElement('div');
    lang.className = 'lx15-lang';
    lang.innerHTML = '<b data-lx15-t="langLabel"></b>';
    /* site language switcher (same 9 languages + lx-language cookie as the rest of the site) */
    lang.setAttribute('translate', 'no');
    var SITE_LANGS = ['en','de','es','fr','it','pt','ja','ko','zh'];
    var curSite = (window.nvI18n && window.nvI18n.lang && window.nvI18n.lang()) || document.documentElement.getAttribute('data-nv-lang') || 'en';
    SITE_LANGS.forEach(function (l) {
      var b = document.createElement('button');
      b.type = 'button';
      b.setAttribute('data-site-lang', l);
      b.setAttribute('aria-pressed', String(l === curSite));
      b.textContent = l.toUpperCase();
      b.onclick = function () {
        if (window.nvI18n && window.nvI18n.set) { window.nvI18n.set(l); }
        else { document.cookie = 'lx-language=' + l + ';path=/;max-age=31536000;samesite=lax'; location.reload(); }
      };
      lang.appendChild(b);
    });
    lang.style.display = 'grid';
    lang.style.gridTemplateColumns = 'repeat(5, 1fr)';
    lang.style.gap = '4px';
    var lbl = lang.querySelector('b'); if (lbl) { lbl.style.gridColumn = '1 / -1'; }
    if (anchor && anchor.nextSibling) sb.insertBefore(lang, anchor.nextSibling);
    else sb.appendChild(lang);

    /* The sidebar copy of the desktop pitch is gone on purpose: the sidebar is
       rendered on every panel, so keeping it would defeat "home panel only". */
  }

  /* =====================================================================
     4. desktop app block on the Overview panel
     ===================================================================== */
  function desktopBlock() {
    var el = document.createElement('section');
    el.className = 'lx15-desk';
    el.id = 'lx15Desk';
    el.innerHTML =
      '<div class="lx15-desk__ico"><svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round">' +
      '<rect x="2.5" y="4" width="19" height="13" rx="2"></rect><path d="M8 20.5h8M12 17v3.5"></path></svg></div>' +
      '<div class="lx15-desk__body">' +
      '<h3 class="lx15-desk__title" data-lx15-t="deskMiniTitle"></h3>' +
      '<p class="lx15-desk__text" data-lx15-t="deskMiniText"></p>' +
      '<span class="lx15-desk__chips"><i>Windows</i><i>macOS</i></span>' +
      '</div>' +
      '<button class="btn btn-ghost btn-sm" type="button" id="lx15DeskCta" data-lx15-t="deskMiniCta"></button>';
    return el;
  }

  function mountDesktop() {
    if ($('lx15Desk')) return;
    /* Owner's call: this belongs on the home panel only. The previous build
       mounted it OUTSIDE the panels, so the promo followed the user into
       Videos, Images, Billing — three download pitches on one screen. It now
       lives inside [data-panel="overview"], right under the stat row, and is
       physically absent from every other section. */
    var home = document.querySelector('[data-panel="overview"]');
    if (!home) return;
    var block = desktopBlock();
    /* Order on the home panel matters: the primary call to action
       ("Turn a photo into a moving shot", #ovResume) has to come first.
       The desktop app is a secondary, "also available" note, so it is
       mounted right AFTER that card, not between the stats and it. */
    var anchor = home.querySelector('#ovResume') || home.querySelector('.stat-row');
    if (anchor && anchor.nextSibling) home.insertBefore(block, anchor.nextSibling);
    else if (anchor) home.appendChild(block);
    else home.insertBefore(block, home.firstChild);
    var cta = $('lx15DeskCta');
    if (cta) cta.onclick = function () {
      if (typeof window.toast === 'function') window.toast(t('deskToast'));
      window.open('https://neuracreation.com/download', '_blank', 'noopener');
    };
  }

  /* =====================================================================
     4b. web generation maintenance notice
     Owner's call: web generation is paused while new tools are wired into
     the browser studio. Clicking Generate must not queue a fake job — it
     opens this notice instead, and points people at the desktop app
     (same account, same models, already shipping) until email tells them
     the web studio is back.
     ===================================================================== */
  function buildMaintenanceModal() {
    var ov = document.createElement('div');
    ov.className = 'ov';
    ov.id = 'lx15MaintModal';
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-modal', 'true');
    ov.setAttribute('aria-labelledby', 'lx15MaintTitle');
    ov.innerHTML =
      '<div class="modal" style="max-width:460px">' +
        '<div class="lx15-desk__ico" style="width:44px;height:44px;border-radius:11px;margin-bottom:14px">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">' +
            '<path d="M14.7 6.3a4 4 0 0 0-5.4 5.4L3 18l3 3 6.3-6.3a4 4 0 0 0 5.4-5.4L15 12l-3-3z"></path>' +
          '</svg>' +
        '</div>' +
        '<h3 id="lx15MaintTitle" data-lx15-t="maintTitle" style="margin:0 0 10px"></h3>' +
        '<p class="muted" data-lx15-t="maintText" style="margin:0 0 18px;line-height:1.55"></p>' +
        '<div style="display:flex;gap:10px;margin-bottom:12px">' +
          '<a class="btn btn-pri" id="lx15MaintWin" target="_blank" rel="noopener" style="flex:1;text-align:center" data-lx15-t="maintWin"></a>' +
          '<a class="btn btn-pri" id="lx15MaintMac" target="_blank" rel="noopener" style="flex:1;text-align:center" data-lx15-t="maintMac"></a>' +
        '</div>' +
        '<p class="muted" data-lx15-t="maintNote" style="margin:0 0 18px;font-size:12.5px"></p>' +
        '<button class="btn btn-ghost" type="button" id="lx15MaintClose" style="width:100%" data-lx15-t="maintClose"></button>' +
      '</div>';
    ov.onclick = function (e) { if (e.target === ov) closeModal('lx15MaintModal'); };
    document.body.appendChild(ov);
    $('lx15MaintWin').href = '/api/desktop_download.php?os=windows';
    $('lx15MaintMac').href = '/api/desktop_download.php?os=macos';
    $('lx15MaintClose').onclick = function () { closeModal('lx15MaintModal'); };
  }
  function mountMaintenanceModal() {
    if ($('lx15MaintModal')) return;
    buildMaintenanceModal();
  }
  function openMaintenanceModal() {
    mountMaintenanceModal();
    applyLangIn($('lx15MaintModal'));
    openModal('lx15MaintModal');
  }

  /* =====================================================================
     4c. generation loading overlay
     Plays for ~2s right after Generate is pressed, before the maintenance
     notice opens — so the click feels like it kicked something off instead
     of jumping straight to "not available yet".
     ===================================================================== */
  function buildLoadingModal() {
    var ov = document.createElement('div');
    ov.className = 'ov';
    ov.id = 'lx15LoadModal';
    ov.setAttribute('role', 'status');
    ov.setAttribute('aria-live', 'polite');
    var logoSrc = (document.querySelector('.sb .lg .dot') || {}).src || '';
    ov.innerHTML =
      '<div class="modal" style="max-width:360px;text-align:center;padding:38px 30px 30px">' +
        '<div class="lx15-load__ring">' +
          '<div class="lx15-load__r1"></div>' +
          '<div class="lx15-load__r2"></div>' +
          '<div class="lx15-load__core"><img alt="" src="' + logoSrc + '"></div>' +
        '</div>' +
        '<p class="lx15-load__status" id="lx15LoadStatus"></p>' +
        '<div class="lx15-load__bar"><div class="lx15-load__fill" id="lx15LoadFill"></div></div>' +
      '</div>';
    document.body.appendChild(ov);
  }
  function mountLoadingModal() {
    if (!$('lx15LoadModal')) buildLoadingModal();
  }
  function openGenLoadingModal(onDone) {
    mountLoadingModal();
    var fill = $('lx15LoadFill'), status = $('lx15LoadStatus');
    var msgs = [t('loadMsg1'), t('loadMsg2'), t('loadMsg3')];
    var step = 0;
    fill.style.width = '0%';
    status.style.opacity = '1';
    status.textContent = msgs[0];
    openModal('lx15LoadModal');
    requestAnimationFrame(function () { requestAnimationFrame(function () { fill.style.width = '100%'; }); });
    var iv = setInterval(function () {
      step++;
      if (step >= msgs.length) return;
      status.style.opacity = '0';
      setTimeout(function () { status.textContent = msgs[step]; status.style.opacity = '1'; }, 180);
    }, 650);
    setTimeout(function () {
      clearInterval(iv);
      closeModal('lx15LoadModal');
      onDone();
    }, 2000);
  }
  /* Replaces the earlier (demo) startGenerate override: Generate no longer
     queues a fake job while the real web pipeline is on hold. It now plays
     a short loading beat, then opens the maintenance notice. */
  window.startGenerate = function () {
    updateSourceReady();
    if ($('genGoBtn').disabled) return;
    closeModal('genModal');
    openGenLoadingModal(function () { openMaintenanceModal(); });
  };

  /* =====================================================================
     5. Venice catalog panel
     ===================================================================== */
  function credits(usd) {
    if (usd === null || usd === undefined) return null;
    return Math.max(1, Math.round(usd / 0.02));            // V14 footer: 1 credit ≈ $0.02
  }

  /* ---------------------------------------------------------------
     Per-model icon. The class an entry already carries in the registry
     (photoreal / creative / fast / edit / flagship / long / reference /
     uncensored) decides the glyph, so a model added to model-profiles.json
     gets its icon with no code change. The vendor favicon rides along as a
     small badge and simply disappears if it fails to load — the card is never
     left with an empty square waiting on a third-party request.
     --------------------------------------------------------------- */
  var ICON_SVG = {
    aperture: '<circle cx="12" cy="12" r="9"/><path d="M12 3v7M21 12h-7M12 21v-7M3 12h7"/>',
    palette:  '<path d="M12 3a9 9 0 1 0 0 18c1.2 0 2-.8 2-1.8 0-.5-.2-.9-.5-1.2-.3-.3-.5-.7-.5-1.2 0-1 .8-1.8 1.8-1.8H17a4 4 0 0 0 4-4c0-4.4-4-8-9-8z"/><circle cx="7.5" cy="11.5" r="1.1"/><circle cx="11" cy="7.5" r="1.1"/><circle cx="15.5" cy="9" r="1.1"/>',
    bolt:     '<path d="M13 2 4 14h6l-1 8 9-12h-6l1-8z"/>',
    wand:     '<path d="M15 4 20 9 8 21H3v-5z"/><path d="M13.5 5.5 18.5 10.5"/><path d="M5 3v3M3.5 4.5h3M18 16v3M16.5 17.5h3"/>',
    star:     '<path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1L3.2 9.5l6.1-.9z"/>',
    film:     '<rect x="3" y="4" width="18" height="16" rx="2.5"/><path d="M8 4v16M16 4v16M3 9h5M3 15h5M16 9h5M16 15h5"/>',
    frames:   '<rect x="3" y="5" width="11" height="11" rx="2"/><path d="M17 8h4v11H10v-4"/><path d="m6 13 2.2-2.4L11 13"/>',
    shield:   '<path d="M12 3 5 6v5.5c0 4.2 2.9 7.6 7 9.5 4.1-1.9 7-5.3 7-9.5V6z"/><path d="M9.5 12.5h5"/>'
  };
  var ICON_LABEL = {
    photoreal: 'icoPhotoreal', creative: 'icoCreative', fast: 'icoFast', edit: 'icoEdit',
    flagship: 'icoFlagship', long: 'icoLong', reference: 'icoReference', uncensored: 'icoShield'
  };

  /* The avatar shows the maker's OWN mark. Every file lives in vendor-logos/
     next to the page: fetched once, checked by eye, then served by us. The
     previous build pointed <img> at Google's favicon service at render time and
     a live count found only 20 of 50 cards actually showing anything - the rest
     were failed requests or Google's grey globe placeholder. A third-party
     request per card is also a needless leak of what the user is browsing.
     Three community checkpoints (Chroma, HappyHorse, Ovi) have no brand site at
     all; they carry an explicit monogram so the grid never shows a blank plate. */
  var LOGO_DIR = '/lk/assets-b/vendor-logos/';

  function monoOf(m) {
    if (m.logo_mono) return m.logo_mono;
    var v = String(m.vendor || '?').replace(/\(.*?\)/g, '').trim().split(/\s+/);
    return ((v.length > 1 ? v[0][0] + v[1][0] : v[0].slice(0, 2)) || '?').toUpperCase();
  }
  function logoUrl(m) { return m.logo_file ? LOGO_DIR + m.logo_file : ''; }

  function iconHtml(m, big) {
    var key = m.icon || 'aperture';
    var glyph = ICON_SVG[key] || ICON_SVG.aperture;
    var cls = m['class'] || 'photoreal';
    var mono = esc(monoOf(m));
    var label = esc((m.vendor || '') + ' \u00b7 ' + t(ICON_LABEL[cls] || 'icoPhotoreal'));
    /* onerror, not a silent gap: if a mark ever fails to load the plate turns
       into the monogram in place, so the tile keeps its size and the row of
       cards does not reflow. */
    /* plate mode comes from the logo's own pixels (logo_plate in the catalog):
       "bleed" for art that already is a tile, "dark" for a white-on-transparent
       mark, "light" (the default white plate) for a dark one. */
    var pmode = m.logo_plate === 'bleed' ? ' lx15-ico__plate--bleed'
              : m.logo_plate === 'dark' ? ' lx15-ico__plate--dark' : '';
    var plate = m.logo_file
      ? '<span class="lx15-ico__plate' + pmode + '">' +
          '<img class="lx15-ico__brand" alt="" loading="lazy" decoding="async" ' +
            'src="' + esc(logoUrl(m)) + '" data-mono="' + mono + '" ' +
            'onerror="var p=this.parentNode;'+
              'p.className=p.className.replace(\' lx15-ico__plate--bleed\',\'\')'+
              '.replace(\' lx15-ico__plate--dark\',\'\')+\' lx15-ico__plate--mono\';' +
              'p.textContent=this.getAttribute(\'data-mono\');">' +
        '</span>'
      : '<span class="lx15-ico__plate lx15-ico__plate--mono">' + mono + '</span>';
    return '<span class="model-card__logo lx15-ico lx15-ico--' + esc(cls) +
      (big ? ' lx15-ico--big' : '') + '" title="' + label + '">' +
      plate +
      '<span class="lx15-ico__cls" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" focusable="false">' + glyph + '</svg>' +
      '</span>' +
      '</span>';
  }

  function prosOf(m) {
    var p = m.pros || {};
    return p[LANG] || p.en || [];
  }
  /* Two plain-language lines: what the model is, and when to reach for it.
     They live in model-profiles.json next to the specs, so a model added to
     the registry explains itself without a code change. */
  function summaryOf(m) {
    var s = m.summary || {};
    return s[LANG] || s.en || [];
  }
  function summaryHtml(m) {
    var lines = summaryOf(m);
    if (!lines.length) return '';
    return '<p class="lx15-tip__sum">' +
      lines.map(function (x) { return esc(x); }).join('<br>') + '</p>';
  }
  function caveatOf(m) {
    return m.caveat ? (m.caveat[LANG] || m.caveat.en) : null;
  }

  /* Specs already proven on the card, repeated in the tooltip footer so the
     hover answers "what will I actually get" without opening the modal. */
  function specLine(m) {
    var p = m.params || {}, bits = [];
    if (m.kind === 'video') {
      if (p.durations && p.durations.length)
        bits.push(p.durations[0] + '–' + p.durations[p.durations.length - 1]);
      if (p.resolutions && p.resolutions.length) bits.push(p.resolutions.join(' / '));
      if (p.aspect_ratios && p.aspect_ratios.length) bits.push(p.aspect_ratios.slice(0, 4).join(' · '));
    } else {
      if (p.resolutions && p.resolutions.length) bits.push(p.resolutions.join(' / '));
      if (p.aspect_ratios && p.aspect_ratios.length) bits.push(p.aspect_ratios.slice(0, 5).join(' · '));
      if (m.max_chars) bits.push('≤ ' + m.max_chars);
    }
    return bits.join('  ·  ');
  }

  /* ---- one shared tooltip node, positioned fixed and flipped at the edges */
  var tipEl = null, tipTimer = null, tipFor = null;

  function tipNode() {
    if (tipEl) return tipEl;
    tipEl = document.createElement('div');
    tipEl.className = 'lx15-tip';
    tipEl.id = 'lx15Tip';
    tipEl.setAttribute('role', 'tooltip');
    tipEl.hidden = true;
    document.body.appendChild(tipEl);
    return tipEl;
  }

  function tipHtml(m) {
    var pros = prosOf(m), cav = caveatOf(m), spec = specLine(m);
    var label = (PROFILES.classes && PROFILES.classes[m['class']])
      ? (PROFILES.classes[m['class']][LANG] || PROFILES.classes[m['class']].en) : m['class'];
    return '<div class="lx15-tip__head">' + iconHtml(m) +
        '<div class="lx15-tip__id"><b>' + esc(m.name) + '</b>' +
        '<span>' + esc(m.vendor) + ' · ' + esc(label) + '</span></div></div>' +
      summaryHtml(m) +
      (pros.length ? '<div class="lx15-tip__cap">' + esc(t('tipPros')) + '</div><ul class="lx15-tip__pros">' +
        pros.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>' : '') +
      (cav ? '<p class="lx15-tip__note"><b>' + esc(t('tipNote')) + ':</b> ' + esc(cav) + '</p>' : '') +
      (spec ? '<p class="lx15-tip__spec">' + esc(spec) + '</p>' : '') +
      '<p class="lx15-tip__cta">' + esc(t('tipOpen')) + '</p>';
  }

  function placeTip(anchorEl) {
    var el = tipNode(), r = anchorEl.getBoundingClientRect();
    el.style.left = '0px'; el.style.top = '0px';           // measure unclamped
    var tw = el.offsetWidth, th = el.offsetHeight, gap = 10, pad = 8;
    var left = r.left + r.width / 2 - tw / 2;
    left = Math.max(pad, Math.min(left, window.innerWidth - tw - pad));
    var top = r.bottom + gap;
    if (top + th > window.innerHeight - pad) {             // flip above
      top = r.top - th - gap;
      if (top < pad) top = Math.max(pad, window.innerHeight - th - pad);
    }
    el.style.left = Math.round(left) + 'px';
    el.style.top = Math.round(top) + 'px';
  }

  function showTip(m, anchorEl) {
    var el = tipNode();
    tipFor = anchorEl;
    el.innerHTML = tipHtml(m);
    el.hidden = false;
    placeTip(anchorEl);
    el.classList.add('is-on');
  }
  function hideTip() {
    if (!tipEl) return;
    clearTimeout(tipTimer);
    tipEl.classList.remove('is-on');
    tipEl.hidden = true;
    tipFor = null;
  }
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') hideTip(); });
  window.addEventListener('scroll', function () { if (tipFor) hideTip(); }, true);
  window.addEventListener('resize', hideTip);

  /* Touch has no hover: a tap opens the modal, which carries the same pros.
     Binding a fake hover there would only swallow the first tap. */
  var HOVER_OK = !(window.matchMedia && window.matchMedia('(hover: none)').matches);

  function bindTip(card, m) {
    if (!prosOf(m).length && !summaryOf(m).length) return;
    card.setAttribute('aria-describedby', 'lx15Tip');
    function openOn(anchor) {
      return function () {
        clearTimeout(tipTimer);
        tipTimer = setTimeout(function () { showTip(m, anchor); }, 110);
      };
    }
    var open = openOn(card);
    if (HOVER_OK) {
      card.addEventListener('mouseenter', open);
      card.addEventListener('mouseleave', hideTip);
      /* Hovering the logo itself re-anchors the card under the icon, which is
         where the pointer already is — the owner asked for the description to
         hang off the logo, not off the far corner of the tile. */
      var logo = card.querySelector('.lx15-ico');
      if (logo) {
        logo.addEventListener('mouseenter', openOn(logo));
        logo.addEventListener('mouseleave', open);
      }
    }
    card.addEventListener('focus', function () { showTip(m, card); });
    card.addEventListener('blur', hideTip);
    card.addEventListener('click', hideTip);
  }

  function modelCard(m) {
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'model-card';
    b.setAttribute('data-lx15-model', m.id);
    b.setAttribute('data-family-name', m.name);
    b.setAttribute('data-badge', m.kind === 'video' ? pipeLabel(m) : 'Text → Image');
    var cr = credits(m.price_usd);
    var price = m.kind === 'video' ? t('priceVideo') : (cr === null ? t('priceQuote') : cr + ' cr');
    var dur = (m.params && m.params.durations && m.params.durations.length)
      ? m.params.durations[0] + '–' + m.params.durations[m.params.durations.length - 1] : '';
    var res = (m.params && m.params.resolutions && m.params.resolutions.length)
      ? m.params.resolutions.slice(0, 3).join(' / ') : '';
    var lead = prosOf(m)[0] || '';
    b.innerHTML =
      iconHtml(m) +
      '<div class="model-card__name">' + esc(m.name) + '</div>' +
      (lead ? '<div class="lx15-card__lead">' + esc(lead) + '</div>' : '') +
      '<div class="model-card__desc">' + esc(m.vendor) + (dur ? ' · ' + esc(dur) : '') +
        (res ? ' · ' + esc(res) : '') + '</div>' +
      '<div class="model-card__foot"><span class="model-card__pipe">' +
        esc(m.kind === 'video' ? pipeLabel(m) : 'Text → Image') + '</span>' +
      '<span class="model-card__price">' + esc(price) + '</span></div>';
    b.onclick = function () { openVeniceModel(m); };
    bindTip(b, m);
    return b;
  }

  function pipeLabel(m) {
    return { t2v: 'Text → Video', i2v: 'Photo → Video', r2v: 'Reference → Video', v2v: 'Video → Video' }[m.pipeline] || 'Video';
  }

  function esc(s) {
    return String(s === null || s === undefined ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  var ORDER = ['photoreal', 'creative', 'fast', 'edit', 'flagship', 'long', 'reference', 'uncensored'];

  var nsfwOn = false;
  try { nsfwOn = sessionStorage.getItem(SS_NSFW) === '1'; } catch (e) {}
  var catalogRenderers = [];

  /* Image models live in the Images tab and video models in the Videos tab —
     the panels the studio already opens on, not a section nobody sees. */
  function buildCatalogFor(kind, panel, headKey) {
    var host = document.querySelector('[data-panel="' + panel + '"]');
    var secId = 'lx15Cat-' + kind;
    if (!host || $(secId)) return;
    var sec = document.createElement('section');
    sec.id = secId;
    sec.setAttribute('data-lx15-cat', kind);
    sec.style.marginTop = '26px';
    sec.innerHTML =
      '<div class="sec-head"><h2 class="disp" data-lx15-t="catTitle"></h2></div>' +
      '<p class="muted lead" data-lx15-t="catLead"></p>' +
      '<div class="lx15-nsfw-gate"><p data-lx15-t="nsfwGate" data-lx15-html="1"></p>' +
      '<button class="btn btn-ghost btn-sm lx15-nsfw-toggle" type="button"></button></div>' +
      '<div class="lx15-cat-body"></div>';
    host.appendChild(sec);

    var body = sec.querySelector('.lx15-cat-body');
    var tgl = sec.querySelector('.lx15-nsfw-toggle');

    function render() {
      body.replaceChildren();
      ORDER.forEach(function (cls) {
        var list = (PROFILES[kind] || []).filter(function (m) { return m['class'] === cls; });
        if (!list.length) return;
        if (cls === 'uncensored' && !nsfwOn) return;
        var label = (PROFILES.classes && PROFILES.classes[cls])
          ? (PROFILES.classes[cls][LANG] || PROFILES.classes[cls].en) : cls;
        var h = document.createElement('div');
        h.innerHTML = '<h4 style="margin:16px 0 8px;font:700 14px/1.3 ui-sans-serif,system-ui;color:#c6bdb6">' +
          esc(label) + ' <span style="opacity:.5;font-weight:600">· ' + list.length + '</span></h4>';
        body.appendChild(h);
        var grid = document.createElement('div');
        grid.className = 'img-products';
        list.forEach(function (m) { grid.appendChild(modelCard(m)); });
        body.appendChild(grid);
      });
      tgl.textContent = nsfwOn ? t('nsfwHide') : t('nsfwShow');
      applyLangIn(sec);          // subtree only — never re-dispatch lx15:lang
    }

    tgl.onclick = function () {
      nsfwOn = !nsfwOn;
      try { sessionStorage.setItem(SS_NSFW, nsfwOn ? '1' : '0'); } catch (e) {}
      catalogRenderers.forEach(function (fn) { fn(); });   // both tabs stay in sync
    };
    catalogRenderers.push(render);
    render();
  }

  function buildCatalog() {
    buildCatalogFor('image', 'images', 'catImages');
    buildCatalogFor('video', 'videos', 'catVideos');
    document.addEventListener('lx15:lang', function () {
      hideTip();
      catalogRenderers.forEach(function (fn) { fn(); });
    });
  }

  /* Open the existing generation modal bound to a real Venice model. */
  function openVeniceModel(m) {
    var durations = (m.params && m.params.durations || []).map(function (d, i) {
      var secs = parseInt(d, 10) || 0;
      var base = parseInt(m.params.durations[0], 10) || 1;
      return { s: secs, m: Math.round((secs / base) * 100) / 100 };
    });
    var qualities = (m.params && m.params.resolutions || []).map(function (r, i) {
      return { l: r, m: 1 + i * 0.3 };
    });
    var cr = credits(m.price_usd) || 10;
    var data = {
      id: 'venice:' + m.id, title: m.name, badge: m.kind === 'video' ? pipeLabel(m) : 'Text → Image',
      type: 'model', price: cr, promptOnly: (m.kind === 'image' || m.pipeline === 't2v'),
      logo: logoUrl(m),
      durations: durations, qualities: qualities,
      /* V14's openGenData reads versionSpec.qualities.length and .aspectRatios
         unconditionally once verified===true — both must be real arrays. */
      versionSpec: {
        label: m.name, price: cr, verified: true,
        source: 'Venice API · ' + m.id,
        qualities: qualities,
        aspectRatios: (m.params && m.params.aspect_ratios) || []
      }
    };
    LX15.pendingModel = m;
    if (typeof window.openGenData === 'function') {
      window.openGenData(data);
      if (typeof window.openModal === 'function') window.openModal('genModal');
      else { var mo = $('genModal'); if (mo) mo.classList.add('on'); }
    }
  }

  /* =====================================================================
     6. negative prompt field + model profile strip inside the modal
     ===================================================================== */
  function buildNegative() {
    var prompt = $('genPrompt');
    if (!prompt || $('lx15Neg')) return;
    var wrap = document.createElement('div');
    wrap.className = 'lx15-neg';
    wrap.id = 'lx15Neg';
    wrap.innerHTML =
      '<label class="lx15-neg__head"><input type="checkbox" id="lx15NegOn">' +
      '<span data-lx15-t="negLabel"></span></label>' +
      '<div class="lx15-neg__body" id="lx15NegBody" hidden>' +
      '<textarea id="lx15NegText" rows="2" maxlength="800" aria-label="Negative prompt" data-lx15-ph="negPh"></textarea>' +
      '<div class="lx15-neg__presets" id="lx15NegPresets"></div>' +
      '<p class="lx15-neg__hint" id="lx15NegHint"></p></div>';
    prompt.parentNode.insertBefore(wrap, prompt.nextSibling);

    var pros = document.createElement('div');
    pros.className = 'lx15-pros';
    pros.id = 'lx15ProsList';
    pros.hidden = true;
    wrap.parentNode.insertBefore(pros, wrap);

    var strip = document.createElement('div');
    strip.className = 'lx15-prof';
    strip.id = 'lx15Prof';
    wrap.parentNode.insertBefore(strip, wrap);

    $('lx15NegOn').onchange = function () {
      $('lx15NegBody').hidden = !this.checked;
      if (this.checked) $('lx15NegText').focus();
    };
    renderPresets();
    document.addEventListener('lx15:lang', renderPresets);
  }

  function renderPresets() {
    var host = $('lx15NegPresets');
    if (!host) return;
    host.replaceChildren();
    var lib = (PROFILES.negative_preset_library && PROFILES.negative_preset_library[LANG]) ||
              (PROFILES.negative_preset_library && PROFILES.negative_preset_library.en) || [];
    lib.forEach(function (p) {
      var b = document.createElement('button');
      b.type = 'button';
      b.textContent = p.label;
      b.onclick = function () {
        var ta = $('lx15NegText');
        var cur = ta.value.trim();
        if (cur.indexOf(p.text) !== -1) return;
        ta.value = cur ? cur.replace(/[,\s]+$/, '') + ', ' + p.text : p.text;
        ta.focus();
      };
      host.appendChild(b);
    });
  }

  /** Re-render the strip + negative hint for the model now selected. */
  function syncModelUi(profile) {
    var strip = $('lx15Prof');
    var neg = $('lx15Neg');
    if (!strip || !neg) return;
    strip.replaceChildren();
    if (!profile) {
      var pl0 = $('lx15ProsList');
      if (pl0) { pl0.innerHTML = ''; pl0.hidden = true; }
      neg.style.display = ''; setHint(null); return;
    }

    function tag(text, cls) {
      var s = document.createElement('span');
      s.textContent = text;
      if (cls) s.className = cls;
      strip.appendChild(s);
    }
    /* Touch users never see the hover card, so the modal repeats the pros. */
    var pl = $('lx15ProsList');
    if (pl) {
      var pr = prosOf(profile), cv = caveatOf(profile);
      pl.innerHTML = summaryHtml(profile) + (pr.length
        ? '<div class="lx15-tip__cap">' + esc(t('tipPros')) + '</div><ul class="lx15-tip__pros">' +
          pr.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>' : '') +
        (cv ? '<p class="lx15-tip__note"><b>' + esc(t('tipNote')) + ':</b> ' + esc(cv) + '</p>' : '');
      pl.hidden = !(pr.length || cv || summaryOf(profile).length);
    }
    tag(profile.name);
    tag(profile.dialect === 'tags' ? t('profDialectTags') : t('profDialectNatural'));
    tag(t('profChars') + ' ' + profile.max_chars);
    var native = profile.negative && profile.negative.mode === 'native';
    tag(native ? t('profNegNative') : t('profNegSoft'), native ? 'is-good' : '');
    if (profile.text_render === 'weak') tag(t('profText'), 'is-warn');
    if (profile.nsfw) tag(t('profNsfw'), 'is-nsfw');
    setHint(profile);
  }

  function setHint(profile) {
    var h = $('lx15NegHint');
    if (!h) return;
    var native = profile && profile.negative && profile.negative.mode === 'native';
    h.textContent = native ? t('negHintNative') : t('negHintSoft');
    h.classList.toggle('is-warn', !!profile && !native);
  }

  /* =====================================================================
     7. prompt assistant v2
     ===================================================================== */
  function assistant() {
    var els = ['paIdea', 'paAnalyze', 'paCompose', 'paApply', 'paStatus', 'paQuestions',
               'paResult', 'paDraft', 'paAssumptions', 'paQuestionList', 'genSpecs'];
    for (var i = 0; i < els.length; i++) if (!$(els[i])) return;

    /* The v7 IIFE attached `input`/`click` listeners that wipe a finished prompt on
       a single keystroke and on a click anywhere in the spec block (audit 2026-09-23).
       Those listeners live in a closure we cannot reach, so drop them by replacing
       the nodes, then attach our own well-behaved ones. */
    ['paIdea', 'genSpecs'].forEach(function (id) {
      var el = $(id);
      el.parentNode.replaceChild(el.cloneNode(true), el);
    });

    var state = { questions: [], history: [], round: 0, busy: false, ctrl: null, rev: 0,
                  intent: null, intentSource: null, lastIdea: '', lastAction: null, undo: null, lastSpecKey: null };

    function status(html, error) {
      var s = $('paStatus');
      s.innerHTML = html;
      s.classList.toggle('pa-error', !!error);
    }
    function busy(on) {
      state.busy = on;
      ['paAnalyze', 'paCompose'].forEach(function (id) { $(id).disabled = on; });
      $('paQuestionList').querySelectorAll('button,textarea').forEach(function (el) { el.disabled = on; });
    }
    function softReset() {
      state.rev++;
      if (state.ctrl) state.ctrl.abort();
      state.ctrl = null; busy(false);
      state.questions = []; state.history = []; state.round = 0; state.intent = null;
      $('paQuestions').hidden = true; $('paResult').hidden = true; status('');
    }

    /* ---- draft persistence (v1 lost everything on reopen) ---------------- */
    function saveDraft() {
      try {
        sessionStorage.setItem(SS_DRAFT, JSON.stringify({
          idea: $('paIdea').value, draft: $('paDraft').value,
          intent: state.intent, history: state.history, round: state.round,
          neg: $('lx15NegText') ? $('lx15NegText').value : '',
          negOn: $('lx15NegOn') ? $('lx15NegOn').checked : false
        }));
      } catch (e) {}
    }
    function loadDraft() {
      try {
        var d = JSON.parse(sessionStorage.getItem(SS_DRAFT) || 'null');
        if (!d || (!d.idea && !d.draft)) return false;
        $('paIdea').value = d.idea || '';
        $('paDraft').value = d.draft || '';
        state.intent = d.intent || null;
        state.history = d.history || [];
        state.round = d.round || 0;
        if ($('lx15NegText') && d.neg) {
          $('lx15NegText').value = d.neg;
          $('lx15NegOn').checked = !!d.negOn;
          $('lx15NegBody').hidden = !d.negOn;
        }
        if (d.draft) $('paResult').hidden = false;
        return true;
      } catch (e) { return false; }
    }

    /* ---- which Venice profile is the current selection? ------------------ */
    function currentProfile() {
      if (LX15.pendingModel) return LX15.pendingModel;
      try {
        var tpl = window.currentTpl || {};
        if (tpl.id && String(tpl.id).indexOf('venice:') === 0) return profileOf(String(tpl.id).slice(7));
        if (tpl.modelId && profileOf(tpl.modelId)) return profileOf(tpl.modelId);
        return guessProfile(tpl.title, tpl.kind);
      } catch (e) { return null; }
    }

    function context() {
      var tpl = window.currentTpl || {};
      var spec = window.currentSpec || {};
      var p = currentProfile();
      return {
        selectionType: tpl.type, title: tpl.type === 'model' ? '' : (tpl.title || ''),
        badge: tpl.badge || '', kind: tpl.kind || 'image',
        durationOrSize: spec.aLabel || '', quality: spec.bLabel || '',
        modelId: p ? p.id : '',
        source: tpl.promptOnly ? 'No source file'
                               : 'A source file is provided; the assistant cannot see its contents'
      };
    }

    function specKey() {
      var s = window.currentSpec || {};
      return [(window.currentTpl || {}).id, s.aLabel, s.bLabel].join('|');
    }

    /* ---- render server answer ------------------------------------------- */
    function render(data) {
      var head = '';
      if (data.questions && data.questions.length && state.round >= 1) {
        head = '<span class="lx15-round">' + esc(t('paRound', state.round)) + '</span><br>';
      }
      status(head + esc(data.summary || ''));
      state.questions = data.questions || [];
      $('paQuestions').hidden = !state.questions.length;
      $('paResult').hidden = !!state.questions.length;
      $('paQuestionList').replaceChildren();

      state.questions.forEach(function (q, i) {
        var wrap = document.createElement('div');
        wrap.className = 'pa-question';
        var label = document.createElement('label');
        label.htmlFor = 'paAnswer' + i;
        label.textContent = (i + 1) + '. ' + q.question;
        wrap.appendChild(label);
        var opts = document.createElement('div');
        opts.className = 'pa-options';
        var answer = document.createElement('textarea');
        answer.id = 'paAnswer' + i; answer.rows = 2; answer.maxLength = 450;
        (q.options || []).forEach(function (o) {
          var b = document.createElement('button');
          b.type = 'button'; b.textContent = o; b.setAttribute('aria-pressed', 'false');
          b.onclick = function () {
            answer.value = o;
            opts.querySelectorAll('button').forEach(function (x) {
              x.setAttribute('aria-pressed', String(x === b));
            });
          };
          opts.appendChild(b);
        });
        answer.oninput = function () {
          opts.querySelectorAll('button').forEach(function (x) { x.setAttribute('aria-pressed', 'false'); });
        };
        wrap.appendChild(opts); wrap.appendChild(answer);
        $('paQuestionList').appendChild(wrap);
      });

      if (!state.questions.length) {
        $('paDraft').value = data.prompt || '';
        state.intent = data.intent || state.intent;
        if (data.negative_prompt && $('lx15NegText') && !$('lx15NegText').value.trim()) {
          $('lx15NegText').value = data.negative_prompt;
          $('lx15NegOn').checked = true;
          $('lx15NegBody').hidden = false;
        }
        renderAdapterNote(data);
      }
      saveDraft();
    }

    function renderAdapterNote(data) {
      var host = $('paAssumptions');
      host.replaceChildren();
      var box = document.createElement('div');
      var noteLang = data.lang || LANG;
      if (data.assumptions && data.assumptions.length) {
        var p = document.createElement('p');
        p.style.margin = '0 0 6px';
        p.textContent = (noteLang === 'ru' ? 'Помощник предположил: ' : 'The assistant assumed: ')
          + data.assumptions.join(' • ');
        box.appendChild(p);
      }
      if (data.adapted_for) {
        var a = document.createElement('div');
        a.className = 'lx15-adapt';
        a.innerHTML = t('paAdapted') + ' <b>' + esc(data.adapted_for) + '</b>';
        var det = document.createElement('details');
        det.innerHTML = '<summary>' + esc(t('paWhatChanged')) + '</summary>';
        var ul = document.createElement('ul');
        function li(txt) { var l = document.createElement('li'); l.textContent = txt; ul.appendChild(l); }
        li((noteLang === 'ru' ? 'Формат: ' : 'Format: ') +
           (data.dialect === 'tags' ? t('profDialectTags') : t('profDialectNatural')));
        li((noteLang === 'ru' ? 'Негатив: ' : 'Negatives: ') +
           (data.negative_mode === 'native' ? t('profNegNative') : t('profNegSoft')));
        if (data.removed_negatives && data.removed_negatives.length) {
          li(t('paRemoved') + ' ' + data.removed_negatives.join(', '));
        }
        (data.warnings || []).forEach(function (w) {
          if (w === 'truncated_to_model_limit') li(t('paTruncated'));
          if (w === 'negative_best_effort') li(t('paBestEffort'));
          if (w === 'text_render_weak') li(t('paTextWeak'));
          if (w === 'audio_unsupported') li(t('paAudioUnsupported'));
        });
        if (data.offline) li(t('paOfflineNote'));
        det.appendChild(ul);
        a.appendChild(det);
        box.appendChild(a);
      }
      host.appendChild(box);
    }

    /* ---- server first, shared offline core second ----------------------------
       Same request contract as the live studio (prompt-assistant-v2.php):
       GET -> {token}; POST {action, idea, context, answers, latestAnswerCount,
       round, negative} -> {summary, questions[], intent, prompt, ...}.
       On a static preview there is no PHP, and when the LLM upstream has no
       credits the server answers 503 — in both cases NVPA (assistant-core.js,
       the same intent schema and adapter rules as the server) takes over and
       the note says so. Only a 422 (bad input / empty intent) is shown as is. */
    var ENDPOINT = 'prompt-assistant-v2.php';
    var NV = window.NVPA || null;
    var serverDown = !/^https?:$/.test(location.protocol);   // file:// has no server at all

    function negativeText() {
      return ($('lx15NegOn') && $('lx15NegOn').checked && $('lx15NegText')) ? $('lx15NegText').value.trim() : '';
    }
    function pipelineOf(profile, ctx) {
      if (profile && profile.pipeline) return profile.pipeline;
      if (ctx.kind !== 'video') return 'image';
      return /source file is provided/i.test(ctx.source || '') ? 'i2v' : 't2v';
    }
    function offlineCtx(profile) {
      var ctx = context();
      ctx.pipeline = pipelineOf(profile, ctx);
      return ctx;
    }
    function mergeUserNegative(intent) {
      var neg = negativeText();
      if (!neg || !intent) return intent;
      var list = (intent.user_negatives || []).slice();
      neg.split(/[,\n;]+/).forEach(function (x) { x = x.trim(); if (x && list.indexOf(x) === -1) list.push(x); });
      intent.user_negatives = list;
      return intent;
    }
    function offlineAnswer(action, idea, answers, round) {
      if (!NV) return null;
      var profile = currentProfile();
      var ctx = offlineCtx(profile);
      var r = NV.offline(action, idea, answers, ctx, profile, round);
      if (r.intent && negativeText()) {
        /* the typed negative field is authoritative, exactly as on the server */
        r.intent = mergeUserNegative(r.intent);
        ctx.lang = r.lang; ctx.haystack = idea + ' ' + negativeText();
        var a = NV.adapt(r.intent, profile, ctx);
        r.prompt = a.prompt; r.negative_prompt = a.negative_prompt; r.warnings = a.warnings;
        r.removed_negatives = a.removed_negatives;
      }
      r.offline = true;
      return r;
    }
    function serverCall(body, signal) {
      return fetch(ENDPOINT, { credentials: 'same-origin', signal: signal })
        .then(function (r) { if (!r.ok) throw new Error('csrf'); return r.json(); })
        .then(function (auth) {
          return fetch(ENDPOINT, {
            method: 'POST', credentials: 'same-origin', signal: signal,
            headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': auth.token },
            body: JSON.stringify(body)
          });
        })
        .then(function (res) {
          return res.json().catch(function () { throw new Error('bad-json'); })
            .then(function (data) {
              if (!res.ok) { var e = new Error(data.error || 'error'); e.http = res.status; throw e; }
              return data;
            });
        });
    }

    function request(action) {
      if (state.busy) return;
      clearTimeout(ideaTimer);   /* a queued "idea changed" banner would overwrite the result */
      var idea = $('paIdea').value.trim();
      if (idea.length < 3) { status(esc(t('paEmpty')), true); $('paIdea').focus(); return; }
      var answers = action === 'compose'
        ? state.history.concat(state.questions.map(function (q, i) {
            var el = $('paAnswer' + i);
            return { question: q.question, answer: el ? el.value.trim() : '' };
          }))
        : [];
      var nextRound = action === 'compose' ? state.round + 1 : 0;
      state.lastAction = action;
      state.lastIdea = idea;

      state.rev++;
      var rev = state.rev;
      busy(true);
      $('paResult').hidden = true;
      status('<span class="lx15-spin"></span>' +
             esc(action === 'analyze' ? t('paAnalysing') : t('paComposing')) +
             ' <span style="opacity:.65">' + esc(t('paWorking')) + '</span>');

      function done(data, viaOffline) {
        if (rev !== state.rev) return;
        state.history = answers; state.round = nextRound;
        state.lastSpecKey = specKey();
        state.intentSource = viaOffline ? 'offline' : 'server';
        render(data);
        busy(false); state.ctrl = null;
      }
      function retryButton(msg) {
        status(esc(msg) + '<button type="button" class="lx15-retry" id="lx15Retry">' + esc(t('paRetry')) + '</button>', true);
        var rb = $('lx15Retry'); if (rb) rb.onclick = function () { request(state.lastAction || 'analyze'); };
        busy(false); state.ctrl = null;
      }
      function fallback() {
        var d = offlineAnswer(action, idea, answers, Math.max(1, nextRound));
        if (!d) { retryButton(LANG === 'ru' ? 'Не удалось связаться с помощником.' : 'Could not reach the assistant.'); return; }
        setTimeout(function () { done(d, true); }, 350);
      }

      if (serverDown) { fallback(); return; }
      state.ctrl = new AbortController();
      var signal = state.ctrl.signal;
      var timer = setTimeout(function () { if (state.ctrl) state.ctrl.abort(); }, 85000);
      serverCall({
        action: action, idea: idea, context: context(), answers: answers,
        latestAnswerCount: action === 'compose' ? state.questions.length : 0,
        round: Math.max(1, nextRound), negative: negativeText(), uiLang: LANG
      }, signal)
        .then(function (data) { clearTimeout(timer); done(data, false); })
        .catch(function (e) {
          clearTimeout(timer);
          if (rev !== state.rev) return;
          /* the server understood us and says the input itself is the problem */
          if (e.http === 422) { retryButton(e.message); return; }
          /* no PHP (404), wrong origin (403), upstream dead (5xx), timeout: go offline */
          serverDown = e.name === 'AbortError' || e.message === 'csrf' || e.message === 'bad-json' ||
                       !e.http || e.http >= 500 || e.http === 403 || e.http === 404;
          fallback();
        });
    }

    /* ---- instant re-adaptation on model/spec change (no AI call) --------- */
    function readapt(msgKey) {
      if (!state.intent || $('paResult').hidden) return;
      var p = currentProfile();
      var idea = state.lastIdea || $('paIdea').value.trim();
      function apply(d, viaOffline) {
        if (!d || !d.prompt) return;
        $('paDraft').value = d.prompt;
        d.assumptions = [];
        d.offline = !!viaOffline;
        renderAdapterNote(d);
        if (msgKey !== false) status(esc(t(msgKey || 'paReadapt')));
        saveDraft();
      }
      function local() {
        if (!NV) return;
        var ctx = offlineCtx(p);
        ctx.lang = NV.detectLang(idea);
        ctx.haystack = idea + ' ' + negativeText();
        apply(NV.adapt(mergeUserNegative(state.intent), p || {}, ctx), state.intentSource === 'offline');
      }
      if (serverDown || state.intentSource === 'offline') { local(); return; }
      serverCall({
        action: 'adapt', intent: state.intent, model: p ? p.id : '',
        kind: (window.currentTpl || {}).kind || 'image',
        duration: (window.currentSpec || {}).aLabel || '',
        haystack: idea + ' ' + negativeText()
      }).then(function (d) { apply(d, false); }).catch(local);
    }

    /* ---- handlers -------------------------------------------------------- */
    $('paAnalyze').onclick = function () { request('analyze'); };
    $('paCompose').onclick = function () { request('compose'); };

    /* Editing the idea no longer nukes a finished prompt — it offers a refresh. */
    var ideaTimer = null;
    $('paIdea').addEventListener('input', function () {
      saveDraft();
      if ($('paResult').hidden && $('paQuestions').hidden) return;
      clearTimeout(ideaTimer);
      ideaTimer = setTimeout(function () {
        status(esc(t('paIdeaChanged')) +
               '<button type="button" class="lx15-retry" id="lx15Upd">' + esc(t('paUpdate')) + '</button>');
        var u = $('lx15Upd');
        if (u) u.onclick = function () { softReset(); request('analyze'); };
      }, 600);
    });

    /* A click in the spec block only matters when a value really changed. */
    $('genSpecs').addEventListener('click', function () {
      setTimeout(function () {
        var k = specKey();
        if (state.lastSpecKey !== null && k !== state.lastSpecKey && !$('paResult').hidden) {
          state.lastSpecKey = k;
          readapt('paReadaptSpec');
        } else {
          state.lastSpecKey = k;
        }
      }, 0);
    });

    /* Apply no longer silently overwrites what the user typed. */
    $('paApply').onclick = function () {
      var text = $('paDraft').value.trim();
      if (!text) {
        status(esc(LANG === 'ru' ? 'Промпт пуст. Соберите его заново.' : 'The prompt is empty. Compose it again.'), true);
        return;
      }
      var field = $('genPrompt');
      var existing = field.value.trim();
      function put(v, msg) {
        state.undo = field.value;
        field.value = v;
        field.dispatchEvent(new Event('input', { bubbles: true }));
        status(esc(msg) + '<button type="button" class="lx15-retry" id="lx15Undo">' + esc(t('paUndo')) + '</button>');
        var ub = $('lx15Undo');
        if (ub) ub.onclick = function () {
          if (state.undo !== null) {
            field.value = state.undo;
            field.dispatchEvent(new Event('input', { bubbles: true }));
            status(esc(t('paUndone')));
          }
        };
        field.focus();
      }
      if (!existing) { put(text, t('paApplied')); return; }
      status(esc(t('paApplyReplace')) +
             '<button type="button" class="lx15-retry" id="lx15Rep">' + esc(t('paReplace')) + '</button>' +
             '<button type="button" class="lx15-retry" id="lx15App">' + esc(t('paAppend')) + '</button>');
      $('lx15Rep').onclick = function () { put(text, t('paApplied')); };
      $('lx15App').onclick = function () { put(existing + '\n' + text, t('paApplied')); };
    };

    /* Reopening the modal restores the draft instead of wiping it. */
    var openPrev = window.openGenData;
    window.openGenData = function (data) {
      var r = openPrev ? openPrev.apply(this, arguments) : undefined;
      var p = LX15.pendingModel || currentProfile();
      LX15.pendingModel = null;
      LX15.activeProfile = p;
      syncModelUi(p);
      state.lastSpecKey = specKey();
      if (loadDraft()) {
        /* the v7 reset() hides the panel; a restored draft is useless unseen */
        var panel = $('paPanel'), toggle = $('paToggle');
        if (panel) panel.hidden = false;
        if (toggle) toggle.setAttribute('aria-expanded', 'true');
        /* the draft came from another model: re-adapt quietly so the note is not stale */
        readapt(false);
        status(esc(t('paRestored')));
      }
      return r;
    };

    $('paDraft').addEventListener('input', saveDraft);
    if ($('lx15NegText')) $('lx15NegText').addEventListener('input', saveDraft);
  }

  /* =====================================================================
     boot
     ===================================================================== */
  var LX15 = window.LX15 = { pendingModel: null, activeProfile: null, t: t, setLang: setLang,
                             profiles: function () { return PROFILES; }, lang: function () { return LANG; } };

  function boot() {
    buildSidebar();
    mountDesktop();
    buildNegative();
    assistant();
    applyLang();
    profilesReady.then(function () {
      buildCatalog();
      renderPresets();
      applyLang();
    });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();

</script><script>
(function(){
  'use strict';
  // Hidden catalogue videos must not occupy every connection before logos load.
  var videos=Array.from(document.querySelectorAll('video[data-lx-media-src]'));
  function activate(video){
    if(document.hidden)return;
    if(!video.getAttribute('src')){video.src=video.dataset.lxMediaSrc;video.load();}
    if(video.dataset.lxAutoplay==='1'){var playing=video.play();if(playing&&playing.catch)playing.catch(function(){});}
  }
  function release(video){
    video.pause();
    if(video.getAttribute('src')){video.removeAttribute('src');video.load();}
  }
  if(!('IntersectionObserver' in window)){
    videos.forEach(function(v){v.src=v.dataset.lxMediaSrc;v.preload='none';v.controls=true;});return;
  }
  var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){
    var v=entry.target;v.dataset.lxVisible=entry.isIntersecting?'1':'0';
    if(entry.isIntersecting)activate(v);else release(v);
  });},{threshold:0.1});
  videos.forEach(function(v){observer.observe(v);});
  // Cards rendered later (history, resume tile, modal preview) are created after this
  // IIFE ran, so the initial querySelectorAll never saw them and their src stayed empty.
  function scan(){
    videos=videos.filter(function(v){return v.isConnected;});
    document.querySelectorAll('video[data-lx-media-src]').forEach(function(v){
      if(videos.indexOf(v)===-1){videos.push(v);observer.observe(v);}
    });
  }
  if('MutationObserver' in window){
    new MutationObserver(function(ms){
      for(var i=0;i<ms.length;i++){if(ms[i].addedNodes.length){scan();return;}}
    }).observe(document.body,{childList:true,subtree:true});
  }
  document.addEventListener('visibilitychange',function(){videos.forEach(function(v){
    if(document.hidden)release(v);else if(v.dataset.lxVisible==='1')activate(v);
  });});
})();

</script><script src="/lk/assets/lk-common.js?v=obf1"></script>
<?php require_once LK_ROOT . '/includes/track_actions.php'; if (function_exists('lx_track_actions')) lx_track_actions(); ?>
<script src="/chat/widget.js?v=sup1010" defer></script>
